  "database_binding_sha256" pg_catalog.text NOT NULL CHECK ("database_binding_sha256" ~ '^[0-9a-f]{64}$'),
  "control_scope_id" pg_catalog.uuid NOT NULL,
  "login_name" pg_catalog.text NOT NULL CHECK (pg_catalog.octet_length("login_name") BETWEEN 1 AND 63 AND "login_name" !~ '[[:cntrl:][:space:]*?]'),
  "login_oid" pg_catalog.oid NOT NULL CHECK ("login_oid"<>0::pg_catalog.oid),
  "resource_identity_sha256" pg_catalog.text NOT NULL CHECK ("resource_identity_sha256" ~ '^[0-9a-f]{64}$'),
  "owner_session_user" pg_catalog.text NOT NULL CHECK (pg_catalog.octet_length("owner_session_user") BETWEEN 1 AND 63 AND "owner_session_user" !~ '[[:cntrl:][:space:]*?]'),
  "owner_login_oid" pg_catalog.oid NOT NULL CHECK ("owner_login_oid"<>0::pg_catalog.oid),
  "owner_effective_user" pg_catalog.text NOT NULL CHECK (pg_catalog.octet_length("owner_effective_user") BETWEEN 1 AND 63 AND "owner_effective_user" !~ '[[:cntrl:][:space:]*?]'),
  "owner_effective_oid" pg_catalog.oid NOT NULL CHECK ("owner_effective_oid"<>0::pg_catalog.oid),
  "recorded_before_commit_at_ms" pg_catalog.int8 NOT NULL CHECK ("recorded_before_commit_at_ms" BETWEEN 0 AND 9007199254740991),
  PRIMARY KEY ("owner_operation_id")
);
