CREATE FUNCTION maezo_d7_control._need(ok pg_catalog.boolean, code pg_catalog.text DEFAULT 'P7D08') RETURNS pg_catalog.void
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN IF ok IS NOT TRUE THEN
 IF code NOT IN ('P7D01','P7D02','P7D03','P7D04','P7D05','P7D06','P7D07','P7D08','P7D09','P7D10','P7D11') THEN code:='P7D08';END IF;
 RAISE EXCEPTION USING ERRCODE=code,MESSAGE=CASE code WHEN 'P7D01' THEN 'AUTH_REFUSED' WHEN 'P7D02' THEN 'SCOPE_REFUSED' WHEN 'P7D03' THEN 'PURPOSE_REFUSED' WHEN 'P7D04' THEN 'STALE_EPOCH' WHEN 'P7D05' THEN 'STALE_GENERATION' WHEN 'P7D06' THEN 'REQUEST_CONFLICT' WHEN 'P7D07' THEN 'PRECONDITION_MISMATCH' WHEN 'P7D09' THEN 'UNAVAILABLE' WHEN 'P7D10' THEN 'PENDING_UNKNOWN' WHEN 'P7D11' THEN 'UNSUPPORTED_ADAPTER' ELSE 'INVALID_BODY' END;
 END IF; END $d7$;
CREATE FUNCTION maezo_d7_control._keys(v pg_catalog.jsonb, names pg_catalog.text[]) RETURNS pg_catalog.void
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN PERFORM maezo_d7_control._need(v IS NOT NULL AND pg_catalog.jsonb_typeof(v)='object');
 PERFORM maezo_d7_control._need((SELECT pg_catalog.array_agg(x ORDER BY x COLLATE "C") FROM pg_catalog.jsonb_object_keys(v) x)=(SELECT pg_catalog.array_agg(x ORDER BY x COLLATE "C") FROM pg_catalog.unnest(names) x));END $d7$;
CREATE FUNCTION maezo_d7_control._sha(v pg_catalog.bytea) RETURNS pg_catalog.text
LANGUAGE sql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$ SELECT pg_catalog.encode(pg_catalog.sha256(v),'hex') $d7$;
CREATE FUNCTION maezo_d7_control._b64(v pg_catalog.bytea) RETURNS pg_catalog.text
LANGUAGE sql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$ SELECT pg_catalog.rtrim(pg_catalog.translate(pg_catalog.replace(pg_catalog.encode(v,'base64'),E'\n',''),'+/','-_'),'=') $d7$;
CREATE FUNCTION maezo_d7_control._unb64(v pg_catalog.text) RETURNS pg_catalog.bytea
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE b bytea;BEGIN PERFORM maezo_d7_control._need(v IS NOT NULL AND v ~ '^[A-Za-z0-9_-]*$' AND pg_catalog.octet_length(v)<=1398104);
 BEGIN b:=pg_catalog.decode(pg_catalog.translate(v,'-_','+/')||pg_catalog.repeat('=',(4-pg_catalog.length(v)%4)%4),'base64');EXCEPTION WHEN OTHERS THEN PERFORM maezo_d7_control._need(false);END;
 PERFORM maezo_d7_control._need(pg_catalog.octet_length(b)<=1048576 AND maezo_d7_control._b64(b)=v);RETURN b;END $d7$;
CREATE FUNCTION maezo_d7_control._w1(v pg_catalog.json, depth pg_catalog.int4 DEFAULT 0) RETURNS pg_catalog.text
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE typ text;answer text;txt text;counted bigint;BEGIN
 PERFORM maezo_d7_control._need(depth<=32 AND v IS NOT NULL);typ:=pg_catalog.json_typeof(v);
 IF typ='object' THEN
  SELECT pg_catalog.count(*) INTO counted FROM pg_catalog.json_each(v);
  PERFORM maezo_d7_control._need(counted=(SELECT pg_catalog.count(DISTINCT key COLLATE "C") FROM pg_catalog.json_each(v)) AND NOT EXISTS(SELECT 1 FROM pg_catalog.json_each(v) WHERE pg_catalog.octet_length(key)<>pg_catalog.char_length(key)));
  SELECT '{'||COALESCE(pg_catalog.string_agg(pg_catalog.to_json(key)::text||':'||maezo_d7_control._w1(value,depth+1),',' ORDER BY key COLLATE "C"),'')||'}' INTO answer FROM pg_catalog.json_each(v);
 ELSIF typ='array' THEN
  PERFORM maezo_d7_control._need(pg_catalog.json_array_length(v)<=1024);
  SELECT '['||COALESCE(pg_catalog.string_agg(maezo_d7_control._w1(value,depth+1),',' ORDER BY ordinal),'')||']' INTO answer FROM pg_catalog.json_array_elements(v) WITH ORDINALITY a(value,ordinal);
 ELSIF typ='number' THEN
  txt:=v::text;PERFORM maezo_d7_control._need(txt ~ '^(0|[1-9][0-9]{0,15})$');PERFORM maezo_d7_control._need(txt::numeric<=9007199254740991);answer:=txt;
 ELSIF typ='string' THEN answer:=pg_catalog.to_json(v#>>'{}')::text;
 ELSIF typ IN ('boolean','null') THEN answer:=v::text;
 ELSE PERFORM maezo_d7_control._need(false);END IF;
 PERFORM maezo_d7_control._need(pg_catalog.octet_length(answer)<=1048576);RETURN answer;END $d7$;
CREATE FUNCTION maezo_d7_control._wire(v pg_catalog.bytea) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE txt text;parsed json;ch text;i int;depth int:=0;quoted boolean:=false;escaped boolean:=false;BEGIN
 PERFORM maezo_d7_control._need(pg_catalog.octet_length(v) BETWEEN 1 AND 1048576);
 BEGIN txt:=pg_catalog.convert_from(v,'UTF8');
 FOR i IN 1..pg_catalog.length(txt) LOOP ch:=pg_catalog.substr(txt,i,1);
  IF quoted THEN IF escaped THEN escaped:=false;ELSIF ch=pg_catalog.chr(92) THEN escaped:=true;ELSIF ch='"' THEN quoted:=false;END IF;
  ELSIF ch='"' THEN quoted:=true;ELSIF ch IN ('[','{') THEN depth:=depth+1;PERFORM maezo_d7_control._need(depth<=33);
  ELSIF ch IN (']','}') THEN depth:=depth-1;PERFORM maezo_d7_control._need(depth>=0);END IF;
 END LOOP;PERFORM maezo_d7_control._need(depth=0 AND NOT quoted);parsed:=txt::json;PERFORM maezo_d7_control._need(maezo_d7_control._w1(parsed)=txt);RETURN parsed::jsonb;
 EXCEPTION WHEN OTHERS THEN PERFORM maezo_d7_control._need(false);END;RETURN NULL;END $d7$;
CREATE FUNCTION maezo_d7_control._canonical(v pg_catalog.jsonb) RETURNS pg_catalog.bytea
LANGUAGE sql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$ SELECT pg_catalog.convert_to(maezo_d7_control._w1(v::json),'UTF8') $d7$;

