CREATE FUNCTION maezo_d7_control._shape(v pg_catalog.jsonb, rule pg_catalog.jsonb, depth pg_catalog.int4 DEFAULT 0) RETURNS pg_catalog.boolean
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE entry record;typ text;matches int:=0;txt text;BEGIN
 IF v IS NULL OR depth>32 THEN RETURN false;END IF;
 IF rule ? '$ref' THEN
  txt:=pg_catalog.replace(rule->>'$ref','#/$defs/','');
  IF NOT maezo_d7_control._shape(v,maezo_d7_control._definitions()->txt,depth) THEN RETURN false;END IF;
  IF txt IN ('Id','Arn','NativeActor','Challenge') AND (pg_catalog.octet_length(v#>>'{}')>255 OR (v#>>'{}') ~ '[[:cntrl:][:space:]*?]') THEN RETURN false;END IF;
  IF txt='Bytes' THEN PERFORM maezo_d7_control._unb64(v#>>'{}');END IF;
  RETURN true;END IF;
 IF rule ? 'oneOf' THEN FOR entry IN SELECT value FROM pg_catalog.jsonb_array_elements(rule->'oneOf') LOOP IF maezo_d7_control._shape(v,entry.value,depth) THEN matches:=matches+1;END IF;END LOOP;RETURN matches=1;END IF;
 IF rule ? 'const' AND v<>rule->'const' THEN RETURN false;END IF;
 IF rule ? 'enum' AND NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(rule->'enum') e WHERE e=v) THEN RETURN false;END IF;
 typ:=rule->>'type';
 IF typ='integer' THEN IF pg_catalog.jsonb_typeof(v)<>'number' OR v::text !~ '^(0|[1-9][0-9]{0,15})$' THEN RETURN false;END IF;
  IF (rule ? 'minimum' AND v::numeric<(rule->>'minimum')::numeric) OR (rule ? 'maximum' AND v::numeric>(rule->>'maximum')::numeric) THEN RETURN false;END IF;
 ELSIF typ IS NOT NULL AND pg_catalog.jsonb_typeof(v)<>typ THEN RETURN false;
 END IF;
 IF typ='object' THEN
  IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements_text(rule->'required') n WHERE NOT v ? n) THEN RETURN false;END IF;
  IF rule->'additionalProperties'='false'::jsonb AND EXISTS(SELECT 1 FROM pg_catalog.jsonb_object_keys(v) n WHERE NOT (rule->'properties') ? n) THEN RETURN false;END IF;
  FOR entry IN SELECT key,value FROM pg_catalog.jsonb_each(v) LOOP IF NOT maezo_d7_control._shape(entry.value,rule->'properties'->entry.key,depth+1) THEN RETURN false;END IF;END LOOP;
 ELSIF typ='array' THEN
  IF (rule ? 'minItems' AND pg_catalog.jsonb_array_length(v)<(rule->>'minItems')::int) OR (rule ? 'maxItems' AND pg_catalog.jsonb_array_length(v)>(rule->>'maxItems')::int) THEN RETURN false;END IF;
  IF rule->'uniqueItems'='true'::jsonb AND (SELECT pg_catalog.count(*)<>pg_catalog.count(DISTINCT x) FROM pg_catalog.jsonb_array_elements(v) x) THEN RETURN false;END IF;
  FOR entry IN SELECT value FROM pg_catalog.jsonb_array_elements(v) LOOP IF NOT maezo_d7_control._shape(entry.value,rule->'items',depth+1) THEN RETURN false;END IF;END LOOP;
 ELSIF typ='string' THEN
  txt:=v#>>'{}';IF (rule ? 'minLength' AND pg_catalog.char_length(txt)<(rule->>'minLength')::int) OR (rule ? 'maxLength' AND pg_catalog.char_length(txt)>(rule->>'maxLength')::int) THEN RETURN false;END IF;
  IF rule ? 'pattern' AND txt !~ pg_catalog.replace(rule->>'pattern','(?:','(') THEN RETURN false;END IF;
 END IF;RETURN true;
 EXCEPTION WHEN OTHERS THEN RETURN false;END $d7$;
CREATE FUNCTION maezo_d7_control._typed(v pg_catalog.jsonb, name pg_catalog.text) RETURNS pg_catalog.void
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN PERFORM maezo_d7_control._need(maezo_d7_control._definitions() ? name);PERFORM maezo_d7_control._need(maezo_d7_control._shape(v,maezo_d7_control._definitions()->name));END $d7$;

CREATE FUNCTION maezo_d7_control.decode_issuer_request_wire(v pg_catalog.bytea) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE j jsonb;BEGIN j:=maezo_d7_control._wire(v);PERFORM maezo_d7_control._typed(j,'IssuerRequest');RETURN j;END $d7$;

CREATE FUNCTION maezo_d7_control.decode_candidate_decision_wire(v pg_catalog.bytea) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE j jsonb;BEGIN j:=maezo_d7_control._wire(v);PERFORM maezo_d7_control._typed(j,'CandidateDecision');RETURN j;END $d7$;

CREATE FUNCTION maezo_d7_control.decode_activation_decision_wire(v pg_catalog.bytea) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE j jsonb;BEGIN j:=maezo_d7_control._wire(v);PERFORM maezo_d7_control._typed(j,'ActivationDecision');RETURN j;END $d7$;

CREATE FUNCTION maezo_d7_control._grant_catalog(protected_roles pg_catalog.oid[]) RETURNS pg_catalog.jsonb
LANGUAGE sql STABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
WITH grants AS (
 SELECT 'table'::text kind,n.nspname schema_name,o.relname object_name,o.oid object_oid,'[]'::jsonb args,'[]'::jsonb cols,a.*
 FROM pg_catalog.pg_class o JOIN pg_catalog.pg_namespace n ON n.oid=o.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(o.relacl,pg_catalog.acldefault('r',o.relowner))) a
 WHERE o.relkind IN ('r','p','v','m','f') AND (n.nspname IN ('maezo_d7_control','maezo_native_v2') OR a.grantee=ANY(protected_roles))
 UNION ALL SELECT 'column',n.nspname,o.relname,o.oid,'[]'::jsonb,pg_catalog.jsonb_build_array(col.attname),a.*
 FROM pg_catalog.pg_attribute col JOIN pg_catalog.pg_class o ON o.oid=col.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=o.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(col.attacl) a
 WHERE col.attnum>0 AND NOT col.attisdropped AND (n.nspname IN ('maezo_d7_control','maezo_native_v2') OR a.grantee=ANY(protected_roles))
 UNION ALL SELECT 'function',n.nspname,o.proname,o.oid,pg_catalog.to_jsonb(pg_catalog.string_to_array(pg_catalog.oidvectortypes(o.proargtypes),', ')),'[]'::jsonb,a.*
 FROM pg_catalog.pg_proc o JOIN pg_catalog.pg_namespace n ON n.oid=o.pronamespace CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(o.proacl,pg_catalog.acldefault('f',o.proowner))) a
 WHERE n.nspname IN ('maezo_d7_control','maezo_native_v2') OR a.grantee=ANY(protected_roles)
 UNION ALL SELECT 'schema',o.nspname,o.nspname,o.oid,'[]'::jsonb,'[]'::jsonb,a.*
 FROM pg_catalog.pg_namespace o CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(o.nspacl,pg_catalog.acldefault('n',o.nspowner))) a
 WHERE o.nspname IN ('maezo_d7_control','maezo_native_v2') OR a.grantee=ANY(protected_roles)
 UNION ALL SELECT 'database','',o.datname,o.oid,'[]'::jsonb,'[]'::jsonb,a.*
 FROM pg_catalog.pg_database o CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(o.datacl,pg_catalog.acldefault('d',o.datdba))) a WHERE o.datname=pg_catalog.current_database()
), objects AS (
 SELECT pg_catalog.jsonb_build_object('object_class',kind,'schema_name',schema_name,'object_name',object_name,'object_oid',object_oid::bigint,'function_argument_types',COALESCE(args,'[]'::jsonb),'column_names',cols,'grantee_oid',grantee::bigint,'grantor_oid',grantor::bigint,'privilege',privilege_type,'grantable',is_grantable) j FROM grants
) SELECT COALESCE(pg_catalog.jsonb_agg(j ORDER BY j::text COLLATE "C"),'[]'::jsonb) FROM objects $d7$;

CREATE FUNCTION maezo_d7_control._fields(v pg_catalog.jsonb) RETURNS pg_catalog.void
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE entry record;BEGIN
 FOR entry IN SELECT key,value FROM pg_catalog.jsonb_each(v) LOOP
  IF entry.key LIKE '%\_sha256' ESCAPE '\' THEN
   IF entry.value<>'null'::jsonb OR entry.key NOT IN ('settled_journal_sha256','managed_registry_sha256','restore_reconciliation_sha256','readiness_result_sha256','restore_receipt_sha256','activation_decision_sha256','current_owner_claim_sha256','previous_claim_sha256','claim_receipt_sha256') THEN PERFORM maezo_d7_control._typed(entry.value,'Sha256');END IF;
  ELSIF entry.key IN ('scope') THEN PERFORM maezo_d7_control._typed(entry.value,'Scope');
  ELSIF entry.key IN ('epoch','revision','generation_id','next_generation_id','expected_fence_revision','expected_generation_revision','previous_root_revision','committed_root_revision','strong_read_revision','reread_revision') THEN PERFORM maezo_d7_control._typed(entry.value,'Positive');
  ELSIF entry.key LIKE '%\_ms' ESCAPE '\' OR entry.key IN ('controller_revision','journal_revision','db_fence_epoch') THEN PERFORM maezo_d7_control._typed(entry.value,'UInt');
  ELSIF entry.key IN ('run_id','control_scope_id','issuer_operation_id','claim_id','installation_id','preparation_id','owner_operation_id','d_preparation_id','native_owner_operation_id','owner_recovery_id','permit_id') THEN IF entry.value<>'null'::jsonb OR entry.key<>'claim_id' THEN PERFORM maezo_d7_control._typed(entry.value,'Uuid');END IF;
  ELSIF entry.key IN ('owner_subject','authenticated_observer_subject','login_name','native_actor','resource_identity','owner_session_user','owner_effective_user') THEN PERFORM maezo_d7_control._typed(entry.value,'Id');
  ELSIF entry.key LIKE '%\_oid' ESCAPE '\' THEN PERFORM maezo_d7_control._typed(entry.value,'Oid');
  END IF;
 END LOOP;END $d7$;
CREATE FUNCTION maezo_d7_control._owner(v pg_catalog.jsonb) RETURNS pg_catalog.void
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN PERFORM maezo_d7_control._keys(v,ARRAY['owner_subject','run_id','epoch']);PERFORM maezo_d7_control._fields(v);END $d7$;
CREATE FUNCTION maezo_d7_control._claim(v pg_catalog.jsonb) RETURNS pg_catalog.void
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN PERFORM maezo_d7_control._keys(v,ARRAY['protocol','control_scope_id','scope','table_identity_sha256','claim_id','previous_claim_sha256','previous_owner','successor_owner','previous_root_revision','committed_root_revision','previous_lease_deadline_ms','claim_observed_at_ms','next_generation_id','journal_revision','pending_index_sha256','managed_registry_sha256','retired_index_sha256','request_sha256']);PERFORM maezo_d7_control._fields(v);
 PERFORM maezo_d7_control._need(v->>'protocol'='maezo.d7-owner-claim.v1');PERFORM maezo_d7_control._owner(v->'previous_owner');PERFORM maezo_d7_control._owner(v->'successor_owner');
 PERFORM maezo_d7_control._need((v->'successor_owner'->>'epoch')::bigint>(v->'previous_owner'->>'epoch')::bigint AND (v->>'committed_root_revision')::bigint=(v->>'previous_root_revision')::bigint+1 AND (v->>'claim_observed_at_ms')::bigint>(v->>'previous_lease_deadline_ms')::bigint);END $d7$;
CREATE FUNCTION maezo_d7_control.decode_owner_lineage_wire(v pg_catalog.bytea) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE j jsonb;r jsonb;claim jsonb;previous jsonb;raw bytea;entry record;latest jsonb;BEGIN
 j:=maezo_d7_control._wire(v);PERFORM maezo_d7_control._keys(j,ARRAY['protocol','scope','control_scope_id','table_identity_sha256','challenge_sha256','authenticated_observer_subject','root_bytes','root_sha256','claim_receipt_bytes','claim_receipt_sha256','ancestor_claim_bytes','ancestor_claim_sha256s','strong_read_revision','reread_revision','observed_at_ms','deadline_ms']);PERFORM maezo_d7_control._fields(j);
 PERFORM maezo_d7_control._need(j->>'protocol'='maezo.d7-owner-lineage-read.v1');raw:=maezo_d7_control._unb64(j->>'root_bytes');PERFORM maezo_d7_control._need(maezo_d7_control._sha(raw)=j->>'root_sha256');r:=maezo_d7_control._wire(raw);
 PERFORM maezo_d7_control._keys(r,ARRAY['schema_version','control_scope_id','scope','owner_subject','run_id','epoch','revision','state','candidate_sha256','trust_profile_sha256','lease_deadline_ms','db_fence_epoch','current_generation_id','next_generation_id','journal_revision','pending_operation_ids','pending_index_sha256','managed_registry_sha256','retired_index_sha256','activation_decision_sha256','restore_receipt_sha256','readiness_result_sha256','restore_state','current_owner_claim_sha256']);PERFORM maezo_d7_control._fields(r);PERFORM maezo_d7_control._typed(r->'state','ControllerState');
 PERFORM maezo_d7_control._need(r->'schema_version'='1'::jsonb AND r->>'restore_state' IN ('RECONCILED','UNRECONCILED') AND pg_catalog.octet_length(raw)<=131072 AND j->'scope'=r->'scope' AND j->'control_scope_id'=r->'control_scope_id' AND j->'strong_read_revision'=r->'revision' AND j->'reread_revision'=r->'revision');
 PERFORM maezo_d7_control._need(pg_catalog.jsonb_typeof(r->'pending_operation_ids')='array' AND pg_catalog.jsonb_array_length(r->'pending_operation_ids')<=1024 AND maezo_d7_control._sha(maezo_d7_control._canonical(r->'pending_operation_ids'))=r->>'pending_index_sha256');
 FOR entry IN SELECT value FROM pg_catalog.jsonb_array_elements(r->'pending_operation_ids') LOOP PERFORM maezo_d7_control._typed(entry.value,'Uuid');END LOOP;
 PERFORM maezo_d7_control._need((SELECT COALESCE(pg_catalog.jsonb_agg(x ORDER BY x::text COLLATE "C"),'[]'::jsonb) FROM (SELECT DISTINCT value x FROM pg_catalog.jsonb_array_elements(r->'pending_operation_ids')) s)=r->'pending_operation_ids');
 PERFORM maezo_d7_control._need(j->'claim_receipt_sha256'=r->'current_owner_claim_sha256' AND pg_catalog.jsonb_typeof(j->'ancestor_claim_bytes')='array' AND pg_catalog.jsonb_array_length(j->'ancestor_claim_bytes')=pg_catalog.jsonb_array_length(j->'ancestor_claim_sha256s') AND pg_catalog.jsonb_array_length(j->'ancestor_claim_bytes')<32);
 IF j->'claim_receipt_bytes'='null'::jsonb THEN PERFORM maezo_d7_control._need(j->'claim_receipt_sha256'='null'::jsonb AND pg_catalog.jsonb_array_length(j->'ancestor_claim_bytes')=0);RETURN j;END IF;
 FOR entry IN SELECT value,ordinality FROM pg_catalog.jsonb_array_elements(j->'ancestor_claim_bytes'||pg_catalog.jsonb_build_array(j->'claim_receipt_bytes')) WITH ORDINALITY LOOP
  raw:=maezo_d7_control._unb64(entry.value#>>'{}');claim:=maezo_d7_control._wire(raw);PERFORM maezo_d7_control._claim(claim);
  PERFORM maezo_d7_control._need(claim->'scope'=j->'scope' AND claim->'control_scope_id'=j->'control_scope_id' AND claim->'table_identity_sha256'=j->'table_identity_sha256');
  IF entry.ordinality<=pg_catalog.jsonb_array_length(j->'ancestor_claim_bytes') THEN PERFORM maezo_d7_control._need(maezo_d7_control._sha(raw)=j->'ancestor_claim_sha256s'->>((entry.ordinality-1)::int));ELSE PERFORM maezo_d7_control._need(maezo_d7_control._sha(raw)=j->>'claim_receipt_sha256');END IF;
  IF previous IS NOT NULL THEN PERFORM maezo_d7_control._need(claim->>'previous_claim_sha256'=maezo_d7_control._sha(maezo_d7_control._canonical(previous)) AND claim->'previous_owner'=previous->'successor_owner' AND (claim->>'previous_root_revision')::bigint>=(previous->>'committed_root_revision')::bigint AND (claim->>'next_generation_id')::bigint>=(previous->>'next_generation_id')::bigint);END IF;previous:=claim;
 END LOOP;
 latest:=previous;PERFORM maezo_d7_control._need(latest->'successor_owner'=pg_catalog.jsonb_build_object('owner_subject',r->'owner_subject','run_id',r->'run_id','epoch',r->'epoch') AND (r->>'revision')::bigint>=(latest->>'committed_root_revision')::bigint AND (r->>'next_generation_id')::bigint>=(latest->>'next_generation_id')::bigint AND (r->>'journal_revision')::bigint>=(latest->>'journal_revision')::bigint);RETURN j;END $d7$;
CREATE FUNCTION maezo_d7_control.decode_owner_restore_wire(v pg_catalog.bytea) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE j jsonb;raw bytea;rows jsonb;row jsonb;BEGIN j:=maezo_d7_control._wire(v);
 PERFORM maezo_d7_control._keys(j,ARRAY['protocol','scope','old_database_binding','new_database_binding','control_scope_id','controller_table_identity_sha256','owner_subject','run_id','epoch','owner_recovery_id','control_observation_bytes','database_observation_bytes','closure_manifest_bytes','closure_manifest_sha256','next_generation_id','retained_generation_index_sha256','pending_index_sha256','journal_revision','observed_at_ms','deadline_ms']);PERFORM maezo_d7_control._fields(j);PERFORM maezo_d7_control._need(j->>'protocol'='maezo.d7-owner-restore-reconciliation.v1');
 PERFORM maezo_d7_control._typed(j->'old_database_binding','DatabaseBinding');PERFORM maezo_d7_control._typed(j->'new_database_binding','DatabaseBinding');
 PERFORM maezo_d7_control._typed(maezo_d7_control._wire(maezo_d7_control._unb64(j->>'control_observation_bytes')),'ControlObservation');PERFORM maezo_d7_control._typed(maezo_d7_control._wire(maezo_d7_control._unb64(j->>'database_observation_bytes')),'DatabaseObservation');
 raw:=maezo_d7_control._unb64(j->>'closure_manifest_bytes');PERFORM maezo_d7_control._need(maezo_d7_control._sha(raw)=j->>'closure_manifest_sha256');rows:=maezo_d7_control._wire(raw);PERFORM maezo_d7_control._need(pg_catalog.jsonb_typeof(rows)='array' AND pg_catalog.jsonb_array_length(rows)<=1024);
 FOR row IN SELECT value FROM pg_catalog.jsonb_array_elements(rows) LOOP PERFORM maezo_d7_control._keys(row,ARRAY['resource_kind','resource_identity','terminal_proof_sha256','observation_sha256']);PERFORM maezo_d7_control._fields(row);PERFORM maezo_d7_control._need(row->>'resource_kind' IN ('role','secret','task','service','task_set','session','pool','prepared_transaction','dispatch','native_history'));END LOOP;
 PERFORM maezo_d7_control._need((j->>'observed_at_ms')::bigint<=(maezo_d7_control._now_ms()) AND maezo_d7_control._now_ms()<(j->>'deadline_ms')::bigint,'P7D09');RETURN j;END $d7$;

CREATE FUNCTION maezo_d7_control._now_ms() RETURNS pg_catalog.int8
LANGUAGE sql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
 SELECT pg_catalog.floor(pg_catalog.date_part('epoch',pg_catalog.clock_timestamp())*1000)::pg_catalog.int8 $d7$;
CREATE FUNCTION maezo_d7_control._installation() RETURNS maezo_d7_control."MZO_PROVISIONING_SCHEMA_VERSION"
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE v maezo_d7_control."MZO_PROVISIONING_SCHEMA_VERSION";BEGIN
 SELECT * INTO STRICT v FROM maezo_d7_control."MZO_PROVISIONING_SCHEMA_VERSION" WHERE component='maezo-d7-control' AND version=1;
 PERFORM maezo_d7_control._need(v.database_oid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=pg_catalog.current_database()) AND v.control_schema_oid=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname='maezo_d7_control'),'P7D02');
 PERFORM maezo_d7_control._need(maezo_d7_control._sha(v.role_acl_manifest_bytes)=v.role_acl_manifest_sha256 AND maezo_d7_control._sha(v.object_manifest_bytes)=v.object_manifest_sha256 AND maezo_d7_control._sha(v.installation_binding_bytes)=v.installation_binding_sha256,'P7D09');
 RETURN v;EXCEPTION WHEN no_data_found OR too_many_rows THEN PERFORM maezo_d7_control._need(false,'P7D09');RETURN NULL;END $d7$;
CREATE FUNCTION maezo_d7_control._role(role_class pg_catalog.text) RETURNS pg_catalog.oid
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE v maezo_d7_control."MZO_PROVISIONING_SCHEMA_VERSION";r jsonb;BEGIN v:=maezo_d7_control._installation();
 SELECT value INTO STRICT r FROM pg_catalog.jsonb_array_elements(maezo_d7_control._wire(v.role_acl_manifest_bytes)->'roles') WHERE value->>'role_class'=role_class;
 PERFORM maezo_d7_control._need(EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE oid=(r->>'role_oid')::oid AND rolname=r->>'role_name'),'P7D01');RETURN (r->>'role_oid')::oid;
 EXCEPTION WHEN no_data_found OR too_many_rows THEN PERFORM maezo_d7_control._need(false,'P7D01');RETURN NULL;END $d7$;
CREATE FUNCTION maezo_d7_control._identity(definer_class pg_catalog.text,caller_class pg_catalog.text) RETURNS pg_catalog.void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN PERFORM maezo_d7_control._need((SELECT oid FROM pg_catalog.pg_roles WHERE rolname=CURRENT_USER)=maezo_d7_control._role(definer_class),'P7D01');
 IF caller_class IS NOT NULL THEN PERFORM maezo_d7_control._need((SELECT oid FROM pg_catalog.pg_roles WHERE rolname=SESSION_USER)=maezo_d7_control._role(caller_class),'P7D01');END IF;
 PERFORM maezo_d7_control._need(pg_catalog.current_setting('transaction_isolation')='read committed' AND pg_catalog.current_setting('server_version_num')::int BETWEEN 160000 AND 169999,'P7D11');END $d7$;
CREATE FUNCTION maezo_d7_control._object_definition(object_oid pg_catalog.oid,kind pg_catalog.text) RETURNS pg_catalog.text
LANGUAGE plpgsql STABLE PARALLEL SAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE j jsonb;BEGIN
 IF kind='function' THEN RETURN maezo_d7_control._sha(pg_catalog.convert_to(pg_catalog.pg_get_functiondef(object_oid),'UTF8'));
 ELSIF kind='schema' THEN SELECT pg_catalog.jsonb_build_object('name',nspname,'owner',nspowner::bigint) INTO j FROM pg_catalog.pg_namespace WHERE oid=object_oid;
 ELSE SELECT pg_catalog.jsonb_build_object('columns',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=object_oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.pg_get_constraintdef(oid,true) ORDER BY conname COLLATE "C"),'[]'::jsonb) FROM pg_catalog.pg_constraint WHERE conrelid=object_oid),
 'indexes',(SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.pg_get_indexdef(indexrelid) ORDER BY indexrelid),'[]'::jsonb) FROM pg_catalog.pg_index WHERE indrelid=object_oid),
 'triggers',(SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.pg_get_triggerdef(oid,true) ORDER BY tgname COLLATE "C"),'[]'::jsonb) FROM pg_catalog.pg_trigger WHERE tgrelid=object_oid AND NOT tgisinternal)) INTO j;
 END IF;PERFORM maezo_d7_control._need(j IS NOT NULL,'P7D09');RETURN maezo_d7_control._sha(maezo_d7_control._canonical(j));END $d7$;
CREATE FUNCTION maezo_d7_control._assert_catalog(excluded_oid pg_catalog.oid DEFAULT NULL) RETURNS pg_catalog.void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE v maezo_d7_control."MZO_PROVISIONING_SCHEMA_VERSION";manifest jsonb;obj jsonb;r jsonb;actual jsonb;p record;g record;event_row record;expected_login boolean;target_oid oid;actual_edges jsonb;expected_edges jsonb;expected_owner oid;grant_record jsonb;effective boolean;
BEGIN v:=maezo_d7_control._installation();manifest:=maezo_d7_control._wire(v.role_acl_manifest_bytes);
 SELECT * INTO event_row FROM maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT" WHERE installation_id=v.installation_id ORDER BY recorded_before_commit_at_ms DESC LIMIT 1;
 IF FOUND THEN PERFORM maezo_d7_control._need(maezo_d7_control._sha(event_row.result_bytes)=event_row.result_sha256,'P7D09');r:=maezo_d7_control._wire(event_row.result_bytes);manifest:=maezo_d7_control._wire(maezo_d7_control._unb64(r->>'owner_catalog_bytes'));
 PERFORM maezo_d7_control._need(maezo_d7_control._sha(maezo_d7_control._unb64(r->>'owner_catalog_bytes'))=r->>'owner_catalog_sha256','P7D09');END IF;
 PERFORM maezo_d7_control._need(pg_catalog.jsonb_array_length(manifest->'roles')<=1024 AND pg_catalog.jsonb_array_length(manifest->'memberships')<=1024 AND pg_catalog.jsonb_array_length(manifest->'object_grants')<=1024,'P7D09');
 FOR obj IN SELECT value FROM pg_catalog.jsonb_array_elements(maezo_d7_control._wire(v.object_manifest_bytes)->'objects') LOOP
  PERFORM maezo_d7_control._need(maezo_d7_control._object_definition((obj->>'object_oid')::oid,obj->>'object_class')=obj->>'definition_sha256','P7D09');
  IF obj->>'object_class'='function' THEN SELECT proowner INTO expected_owner FROM pg_catalog.pg_proc WHERE oid=(obj->>'object_oid')::oid;
  ELSIF obj->>'object_class'='schema' THEN SELECT nspowner INTO expected_owner FROM pg_catalog.pg_namespace WHERE oid=(obj->>'object_oid')::oid;
  ELSE SELECT relowner INTO expected_owner FROM pg_catalog.pg_class WHERE oid=(obj->>'object_oid')::oid;END IF;
  PERFORM maezo_d7_control._need(expected_owner=(obj->>'owner_oid')::oid,'P7D01');
 END LOOP;
 PERFORM maezo_d7_control._need((SELECT pg_catalog.count(*) FROM pg_catalog.pg_proc WHERE pronamespace=v.control_schema_oid)=(SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(maezo_d7_control._wire(v.object_manifest_bytes)->'objects') x WHERE x->>'object_class'='function'),'P7D09');
 PERFORM maezo_d7_control._need((SELECT pg_catalog.count(*) FROM pg_catalog.pg_class WHERE relnamespace=v.control_schema_oid AND relkind IN ('r','p','v','m','S','f'))=7,'P7D09');
 FOR r IN SELECT value FROM pg_catalog.jsonb_array_elements(manifest->'roles') WHERE excluded_oid IS NULL OR (value->>'role_oid')::oid<>excluded_oid LOOP
  target_oid:=(r->>'role_oid')::oid;expected_login:=(r->>'rolcanlogin')::boolean;
  IF r->>'role_class' IN ('generation login','one-shot login') THEN
   SELECT * INTO g FROM maezo_d7_control."MZO_RUNTIME_ADMISSION" WHERE login_oid=target_oid;
   IF FOUND THEN expected_login:=g.status='OPEN';
    IF expected_login THEN PERFORM maezo_d7_control._need(EXISTS(SELECT 1 FROM maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT" i WHERE i.generation_id=g.generation_id AND i.tenant=g.tenant AND i.environment=g.environment AND i.engine_name=g.engine_name AND i.operation IN ('admit_candidate_login','open_runtime_generation') AND i.recorded_before_commit_at_ms=g.opened_at_ms),'P7D09');END IF;
   ELSE SELECT * INTO p FROM maezo_d7_control."MZO_PROVISIONING_PERMIT" WHERE login_oid=target_oid;
    expected_login:=FOUND AND p.state='ISSUED';
    IF FOUND AND p.state='REVOKED' THEN PERFORM maezo_d7_control._need(p.revoked_by_issuer_operation_id IS NOT NULL AND EXISTS(SELECT 1 FROM maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT" i WHERE i.issuer_operation_id=p.revoked_by_issuer_operation_id AND i.operation IN ('revoke_permit','reconcile_fence')),'P7D09');END IF;
   END IF;
  END IF;
  SELECT pg_catalog.jsonb_build_object('role_class',r->'role_class','role_name',rolname,'role_oid',oid::bigint,'rolcanlogin',rolcanlogin,'rolsuper',rolsuper,'rolcreaterole',rolcreaterole,'rolcreatedb',rolcreatedb,'rolreplication',rolreplication,'rolbypassrls',rolbypassrls,'rolinherit',rolinherit) INTO actual FROM pg_catalog.pg_roles WHERE oid=target_oid AND rolname=r->>'role_name';
  PERFORM maezo_d7_control._need(actual IS NOT NULL AND actual=pg_catalog.jsonb_set(r,'{rolcanlogin}',pg_catalog.to_jsonb(expected_login)),'P7D01');
  IF r->>'role_class' IN ('generation login','one-shot login') THEN
   PERFORM maezo_d7_control._need(pg_catalog.has_database_privilege(target_oid,v.database_oid,'CONNECT')=expected_login,'P7D01');
  END IF;
 END LOOP;
 -- Complete membership closure for every protected role; every independent option matters.
 WITH RECURSIVE related(oid) AS (
  SELECT (x->>'role_oid')::oid FROM pg_catalog.jsonb_array_elements(manifest->'roles') x
  UNION SELECT CASE WHEN a.roleid=r.oid THEN a.member ELSE a.roleid END FROM pg_catalog.pg_auth_members a JOIN related r ON a.roleid=r.oid OR a.member=r.oid)
 SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('role_oid',a.roleid::bigint,'member_oid',a.member::bigint,'grantor_oid',a.grantor::bigint,'admin_option',a.admin_option,'inherit_option',a.inherit_option,'set_option',a.set_option) ORDER BY a.roleid,a.member,a.grantor),'[]'::jsonb) INTO actual_edges FROM pg_catalog.pg_auth_members a WHERE (a.roleid IN (SELECT oid FROM related) OR a.member IN (SELECT oid FROM related)) AND (excluded_oid IS NULL OR (a.roleid<>excluded_oid AND a.member<>excluded_oid));
 SELECT COALESCE(pg_catalog.jsonb_agg(x ORDER BY (x->>'role_oid')::bigint,(x->>'member_oid')::bigint,(x->>'grantor_oid')::bigint),'[]'::jsonb) INTO expected_edges FROM pg_catalog.jsonb_array_elements(manifest->'memberships') x WHERE excluded_oid IS NULL OR ((x->>'role_oid')::oid<>excluded_oid AND (x->>'member_oid')::oid<>excluded_oid);
 PERFORM maezo_d7_control._need(pg_catalog.jsonb_array_length(actual_edges)<=1024 AND actual_edges=expected_edges,'P7D01');
 -- Exact complete grant set; only current protected LOGIN/CONNECT overlay may differ.
 actual_edges:=maezo_d7_control._grant_catalog(ARRAY(SELECT (x->>'role_oid')::oid FROM pg_catalog.jsonb_array_elements(manifest->'roles') x));
 IF excluded_oid IS NOT NULL THEN SELECT COALESCE(pg_catalog.jsonb_agg(x ORDER BY x::text COLLATE "C"),'[]'::jsonb) INTO actual_edges FROM pg_catalog.jsonb_array_elements(actual_edges) x WHERE (x->>'grantee_oid')::oid<>excluded_oid;END IF;
 SELECT COALESCE(pg_catalog.jsonb_agg(x),'[]'::jsonb) INTO expected_edges FROM pg_catalog.jsonb_array_elements(manifest->'object_grants') x WHERE NOT (x->>'object_class'='database' AND x->>'privilege'='CONNECT' AND EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(manifest->'roles') r WHERE (r->>'role_oid')::oid=(x->>'grantee_oid')::oid AND r->>'role_class' IN ('generation login','one-shot login')));
 FOR p IN SELECT login_oid FROM maezo_d7_control."MZO_RUNTIME_ADMISSION" WHERE status='OPEN' UNION SELECT login_oid FROM maezo_d7_control."MZO_PROVISIONING_PERMIT" WHERE state='ISSUED' AND principal_origin->>'kind'='owner_prepared_one_shot' LOOP
  expected_edges:=expected_edges||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('object_class','database','schema_name','','object_name',pg_catalog.current_database(),'object_oid',v.database_oid::bigint,'function_argument_types','[]'::jsonb,'column_names','[]'::jsonb,'grantee_oid',p.login_oid::bigint,'grantor_oid',maezo_d7_control._role('D issuer-function owner')::bigint,'privilege','CONNECT','grantable',false));
 END LOOP;
 SELECT COALESCE(pg_catalog.jsonb_agg(x ORDER BY x::text COLLATE "C"),'[]'::jsonb) INTO expected_edges FROM pg_catalog.jsonb_array_elements(expected_edges) x WHERE excluded_oid IS NULL OR (x->>'grantee_oid')::oid<>excluded_oid;
 PERFORM maezo_d7_control._need(pg_catalog.jsonb_array_length(actual_edges)<=1024 AND actual_edges=expected_edges AND NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(actual_edges) x WHERE x->>'grantee_oid'='0'),'P7D01');
 -- Every birth remains nonreusable after qualified removal; no synthetic live OID.
 FOR event_row IN SELECT * FROM maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT" WHERE event='PREPARED' AND (excluded_oid IS NULL OR login_oid<>excluded_oid) LOOP
  IF EXISTS(SELECT 1 FROM maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT" x WHERE x.preparation_id=event_row.preparation_id AND x.event='REMOVED') THEN
   PERFORM maezo_d7_control._need(NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE oid=event_row.login_oid OR rolname=event_row.login_name),'P7D01');
  ELSE PERFORM maezo_d7_control._need(EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(manifest->'roles') x WHERE (x->>'role_oid')::oid=event_row.login_oid AND x->>'role_name'=event_row.login_name),'P7D09');END IF;
 END LOOP;
END $d7$;
CREATE FUNCTION maezo_d7_control._database(f maezo_d7_control."MZO_PROVISIONING_FENCE") RETURNS pg_catalog.void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE b jsonb;v maezo_d7_control."MZO_PROVISIONING_SCHEMA_VERSION";BEGIN v:=maezo_d7_control._installation();b:=maezo_d7_control._wire(f.database_binding_bytes);
 PERFORM maezo_d7_control._typed(b,'DatabaseBinding');PERFORM maezo_d7_control._need(maezo_d7_control._sha(f.database_binding_bytes)=f.database_binding_sha256 AND b->>'database_incarnation'=f.database_incarnation::text,'P7D02');
 PERFORM maezo_d7_control._need((b->>'database_oid')::oid=v.database_oid AND b->>'database_name'=pg_catalog.current_database() AND (b->>'schema_oid')::oid=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname=b->>'schema_name'),'P7D02');END $d7$;
CREATE FUNCTION maezo_d7_control._proof(q pg_catalog.jsonb,operation pg_catalog.text,f maezo_d7_control."MZO_PROVISIONING_FENCE",successor pg_catalog.boolean DEFAULT false) RETURNS pg_catalog.void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE now_ms bigint;BEGIN
 PERFORM maezo_d7_control._keys(q,ARRAY['protocol','scope','run_id','epoch','operation','controller_state','controller_revision','trust_profile_sha256','control_observation_sha256','database_observation_sha256','observation_pair_sha256','observed_at_ms','observation_deadline_ms','controller_lease_deadline_ms','journal_revision','pending_index_sha256','settled_journal_sha256','managed_registry_sha256','restore_reconciliation_sha256']);
 PERFORM maezo_d7_control._fields(q);PERFORM maezo_d7_control._need(q->>'protocol'='maezo.d7-operation-proof.v1' AND q->>'operation'=operation);PERFORM maezo_d7_control._typed(q->'scope','Scope');PERFORM maezo_d7_control._typed(q->'run_id','Uuid');PERFORM maezo_d7_control._typed(q->'epoch','Positive');PERFORM maezo_d7_control._typed(q->'controller_state','ControllerState');
 PERFORM maezo_d7_control._need(q->'scope'=pg_catalog.jsonb_build_object('account',f.account,'region',f.region,'tenant',f.tenant,'environment',f.environment,'engine_name',f.engine_name,'database_binding',maezo_d7_control._wire(f.database_binding_bytes)),'P7D02');
 IF NOT successor THEN PERFORM maezo_d7_control._need(q->>'run_id'=f.owner_run_id::text AND (q->>'epoch')::bigint=f.epoch,'P7D04');END IF;
 PERFORM maezo_d7_control._need(q->>'trust_profile_sha256'=f.trust_profile_sha256,'P7D01');
 PERFORM maezo_d7_control._need(q->>'observation_pair_sha256'=maezo_d7_control._sha(maezo_d7_control._canonical(pg_catalog.jsonb_build_object('control_observation_sha256',q->'control_observation_sha256','database_observation_sha256',q->'database_observation_sha256'))));
 now_ms:=maezo_d7_control._now_ms();PERFORM maezo_d7_control._need((q->>'observed_at_ms')::bigint<=now_ms AND now_ms<LEAST((q->>'observation_deadline_ms')::bigint,(q->>'controller_lease_deadline_ms')::bigint) AND (q->>'observation_deadline_ms')::bigint-(q->>'observed_at_ms')::bigint<=5000 AND (q->>'controller_lease_deadline_ms')::bigint-(q->>'observed_at_ms')::bigint<=120000,'P7D09');
END $d7$;

CREATE FUNCTION maezo_d7_control._close_proofs(t pg_catalog.text,e pg_catalog.text,n pg_catalog.text) RETURNS pg_catalog.void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN
 PERFORM generation_id FROM maezo_d7_control."MZO_RUNTIME_ADMISSION" WHERE tenant=t AND environment=e AND engine_name=n ORDER BY generation_id FOR UPDATE;
 UPDATE maezo_d7_control."MZO_RUNTIME_ADMISSION" SET revision=revision+1,phase_proof_bytes=NULL,phase_proof_sha256=NULL,valid_until_ms=NULL,observation_pair_sha256=NULL,observation_deadline_ms=NULL,restore_receipt_sha256=NULL,readiness_result_sha256=NULL,journal_revision=NULL,settled_journal_sha256=NULL,proof_issuer_operation_id=NULL,phase=CASE WHEN status='RETIRED' THEN 'RETIREMENT' ELSE 'UNADMITTED' END WHERE tenant=t AND environment=e AND engine_name=n AND (phase_proof_bytes IS NOT NULL OR phase NOT IN ('UNADMITTED','RETIREMENT'));
 UPDATE maezo_d7_control."MZO_PROVISIONING_FENCE" SET current_generation_id=NULL,controller_lease_deadline_ms=NULL,observed_at_ms=NULL,observation_deadline_ms=NULL,control_observation_sha256=NULL,database_observation_sha256=NULL,observation_pair_sha256=NULL,restore_reconciliation_sha256=NULL WHERE tenant=t AND environment=e AND engine_name=n;
END $d7$;
CREATE FUNCTION maezo_d7_control._login(target_oid pg_catalog.oid,target_name pg_catalog.text,enabled pg_catalog.boolean) RETURNS pg_catalog.void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN PERFORM maezo_d7_control._need(EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE oid=target_oid AND rolname=target_name AND NOT rolsuper AND NOT rolreplication AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolbypassrls),'P7D01');
 PERFORM maezo_d7_control._need(pg_catalog.octet_length(target_name)<=63 AND EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE roleid=target_oid AND member=maezo_d7_control._role('D issuer-function owner') AND admin_option AND NOT inherit_option AND NOT set_option),'P7D01');
 -- Identifiers come exclusively from protected birth/G/permit rows and actual catalogs.
 IF enabled THEN EXECUTE pg_catalog.format('ALTER ROLE %I LOGIN',target_name);EXECUTE pg_catalog.format('GRANT CONNECT ON DATABASE %I TO %I',pg_catalog.current_database(),target_name);
 ELSE EXECUTE pg_catalog.format('ALTER ROLE %I NOLOGIN',target_name);EXECUTE pg_catalog.format('REVOKE CONNECT ON DATABASE %I FROM %I',pg_catalog.current_database(),target_name);END IF;
END $d7$;
CREATE FUNCTION maezo_d7_control._decision(core pg_catalog.jsonb,d pg_catalog.jsonb,request pg_catalog.jsonb) RETURNS pg_catalog.void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE k text;ref jsonb;BEGIN PERFORM maezo_d7_control._typed(core,'GenerationCore');
 PERFORM maezo_d7_control._need(d->'generation_core'=core AND d->'scope'=request->'scope' AND d->'run_id'=request->'run_id' AND d->'epoch'=request->'epoch' AND core->'scope'=d->'scope' AND core->'epoch'=d->'epoch' AND core->'purpose'=d->'purpose');
 FOR k IN SELECT pg_catalog.unnest(ARRAY['image_sha256','config_set_sha256']) LOOP PERFORM maezo_d7_control._need(d->k=core->k);END LOOP;
 FOR k IN SELECT pg_catalog.unnest(ARRAY['image_sha256','config_set_sha256','task_role','execution_role','network_binding']) LOOP PERFORM maezo_d7_control._need(core->k=core->'task_definition_revision'->k);END LOOP;
 PERFORM maezo_d7_control._need(core->'task_definition_revision'->>'arn' ~ (':'||(core->'task_definition_revision'->>'revision')||'$'));
 FOR k IN SELECT pg_catalog.unnest(ARRAY['deployment_receipt','grant_receipt']) LOOP ref:=d->k;
  PERFORM maezo_d7_control._need(EXISTS(SELECT 1 FROM maezo_d7_control."MZO_PROVISIONING_RECEIPT" r WHERE r.tenant=ref->'receipt_key'->>'tenant' AND r.environment=ref->'receipt_key'->>'environment' AND r.engine_name=ref->'receipt_key'->>'engine_name' AND r.operation=ref->'receipt_key'->>'operation' AND r.run_id=(ref->'receipt_key'->>'run_id')::uuid AND r.request_sha256=ref->>'request_sha256' AND r.result_sha256=ref->>'result_sha256'),'P7D07');
 END LOOP;
END $d7$;
CREATE FUNCTION maezo_d7_control._permit_origin(origin pg_catalog.jsonb,login_name pg_catalog.text,login_oid pg_catalog.oid,operation pg_catalog.text,purpose pg_catalog.text,scope pg_catalog.jsonb) RETURNS pg_catalog.text
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE v maezo_d7_control."MZO_PROVISIONING_SCHEMA_VERSION";birth maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT";binding jsonb;manifest jsonb;principal jsonb;actor text;matches bigint;
BEGIN
 PERFORM maezo_d7_control._need(pg_catalog.octet_length(maezo_d7_control._canonical(origin))<=4096);
 IF origin->>'kind'='owner_prepared_one_shot' THEN
  PERFORM maezo_d7_control._keys(origin,ARRAY['kind','preparation_id']);PERFORM maezo_d7_control._typed(origin->'preparation_id','Uuid');
  SELECT * INTO birth FROM maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT" WHERE preparation_id=(origin->>'preparation_id')::uuid AND event='PREPARED';
  PERFORM maezo_d7_control._need(FOUND AND birth.login_oid=login_oid AND birth.login_name=login_name AND birth.tenant=scope->>'tenant' AND birth.environment=scope->>'environment' AND birth.engine_name=scope->>'engine_name','P7D01');
  PERFORM maezo_d7_control._need(maezo_d7_control._sha(birth.result_bytes)=birth.result_sha256 AND NOT EXISTS(SELECT 1 FROM maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT" x WHERE x.preparation_id=birth.preparation_id AND x.event='REMOVED'),'P7D09');
  binding:=maezo_d7_control._wire(birth.result_bytes);principal:=binding->'principal';
  PERFORM maezo_d7_control._need(binding->'scope'=scope AND principal->>'kind'='one_shot' AND principal->>'purpose'=purpose,'P7D03');actor:=principal->>'native_actor';
 ELSE
  PERFORM maezo_d7_control._keys(origin,ARRAY['kind','installation_id','installation_binding_sha256','role_acl_manifest_sha256','role_class','native_actor']);
  PERFORM maezo_d7_control._need(origin->>'kind'='installation_receipt_reader' AND operation='receipt' AND purpose='receipt_read','P7D03');
  PERFORM maezo_d7_control._typed(origin->'installation_id','Uuid');PERFORM maezo_d7_control._typed(origin->'installation_binding_sha256','Sha256');PERFORM maezo_d7_control._typed(origin->'role_acl_manifest_sha256','Sha256');PERFORM maezo_d7_control._typed(origin->'native_actor','Id');
  PERFORM maezo_d7_control._need(origin->>'role_class' IN ('actual issuer login','scoped D observer login'),'P7D01');
  v:=maezo_d7_control._installation();binding:=maezo_d7_control._wire(v.installation_binding_bytes);manifest:=maezo_d7_control._wire(v.role_acl_manifest_bytes);
  PERFORM maezo_d7_control._need(origin->>'installation_id'=v.installation_id::text AND origin->>'installation_binding_sha256'=v.installation_binding_sha256 AND origin->>'role_acl_manifest_sha256'=v.role_acl_manifest_sha256,'P7D01');
  PERFORM maezo_d7_control._need(binding->>'protocol'='maezo.d7-installation-binding.v1' AND binding->>'component'=v.component AND binding->'version'='1'::jsonb AND binding->>'installation_id'=v.installation_id::text AND binding->'database_binding'=scope->'database_binding','P7D02');
  PERFORM maezo_d7_control._need(pg_catalog.jsonb_typeof(binding->'issuer_scopes')='array' AND EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(binding->'issuer_scopes') x WHERE x=scope),'P7D02');
  SELECT count(*),min(x->>'native_actor') INTO matches,actor FROM pg_catalog.jsonb_array_elements(manifest->'operational_principals') x WHERE x->>'purpose'='receipt_read' AND x->>'login_name'=login_name AND (x->>'login_oid')::oid=login_oid;
  PERFORM maezo_d7_control._need(matches=1 AND actor=origin->>'native_actor','P7D01');
  PERFORM maezo_d7_control._need((SELECT count(*) FROM pg_catalog.jsonb_array_elements(manifest->'roles') x WHERE x->>'role_class'=origin->>'role_class' AND x->>'role_name'=login_name AND (x->>'role_oid')::oid=login_oid)=1 AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE oid=login_oid AND rolname=login_name AND rolcanlogin) AND pg_catalog.has_database_privilege(login_oid,v.database_oid,'CONNECT'),'P7D01');
 END IF;
 PERFORM maezo_d7_control._typed(pg_catalog.to_jsonb(actor),'Id');RETURN actor;
END $d7$;
ALTER TABLE maezo_d7_control."MZO_PROVISIONING_PERMIT" ADD CONSTRAINT d7_origin_shape CHECK (
  pg_catalog.jsonb_typeof(principal_origin)='object' AND pg_catalog.octet_length(maezo_d7_control._canonical(principal_origin))<=4096 AND
  ((principal_origin->>'kind'='owner_prepared_one_shot' AND principal_origin-ARRAY['kind','preparation_id']='{}'::jsonb AND principal_origin ?& ARRAY['kind','preparation_id'] AND pg_catalog.jsonb_typeof(principal_origin->'preparation_id')='string') OR
   (principal_origin->>'kind'='installation_receipt_reader' AND principal_origin-ARRAY['kind','installation_id','installation_binding_sha256','role_acl_manifest_sha256','role_class','native_actor']='{}'::jsonb AND principal_origin ?& ARRAY['kind','installation_id','installation_binding_sha256','role_acl_manifest_sha256','role_class','native_actor'] AND principal_origin->>'role_class' IN ('actual issuer login','scoped D observer login'))));
CREATE FUNCTION maezo_d7_control._issuer(q pg_catalog.jsonb,op pg_catalog.text) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE f maezo_d7_control."MZO_PROVISIONING_FENCE";g maezo_d7_control."MZO_RUNTIME_ADMISSION";p maezo_d7_control."MZO_PROVISIONING_PERMIT";r maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT";birth maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT";body jsonb;proof jsonb;logical jsonb;core jsonb;dec jsonb;owner_result jsonb;lineage jsonb;root jsonb;claim jsonb;old_owner jsonb;restore jsonb;wire bytea;decision_wire bytea;request_wire bytea;result_wire bytea;request_hash text;now_ms bigint;gid bigint;gen_op boolean;successor boolean;initial_status text;expected_owner jsonb;issuer_oid oid;definer_oid oid;next_id bigint;state text;result jsonb;
BEGIN
 PERFORM maezo_d7_control._identity('D issuer-function owner','actual issuer login');issuer_oid:=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=SESSION_USER);definer_oid:=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=CURRENT_USER);
 PERFORM maezo_d7_control._keys(q,ARRAY['protocol','scope','run_id','epoch','issuer_operation_id','expected_fence_revision','request','proof']);PERFORM maezo_d7_control._fields(q);PERFORM maezo_d7_control._need(q->>'protocol'='maezo.d7-store-call.v1' AND pg_catalog.octet_length(maezo_d7_control._canonical(q))<=1048576);
 SELECT * INTO f FROM maezo_d7_control."MZO_PROVISIONING_FENCE" WHERE tenant=q->'scope'->>'tenant' AND environment=q->'scope'->>'environment' AND engine_name=q->'scope'->>'engine_name' FOR UPDATE;
 PERFORM maezo_d7_control._need(FOUND,'P7D02');body:=q->'request';proof:=q->'proof';gen_op:=op IN ('prepare_generation','admit_candidate_login','open_runtime_generation','retire_generation');successor:=op='reconcile_fence' AND body->>'mode'<>'current_owner_reconcile';
 IF NOT(op='reconcile_fence' AND body->>'mode'='database_restore') THEN PERFORM maezo_d7_control._database(f);END IF;PERFORM maezo_d7_control._assert_catalog();
 IF op='record_current_proof' THEN
  PERFORM maezo_d7_control._keys(body,ARRAY['operation','generation_id','expected_generation_revision','phase_proof_bytes','phase_proof_sha256']);wire:=maezo_d7_control._unb64(body->>'phase_proof_bytes');PERFORM maezo_d7_control._need(maezo_d7_control._sha(wire)=body->>'phase_proof_sha256' AND maezo_d7_control._wire(wire)=proof);
  PERFORM maezo_d7_control._keys(proof,ARRAY['protocol','scope','run_id','epoch','generation_id','generation_binding_sha256','decision_sha256','purpose','phase','controller_state','controller_revision','source','tree','image_sha256','config_set_sha256','trust_profile_sha256','control_observation_sha256','database_observation_sha256','observation_pair_sha256','observed_at_ms','observation_deadline_ms','controller_lease_deadline_ms','restore_receipt_sha256','readiness_result_sha256','journal_revision','settled_journal_sha256','managed_registry_sha256','pending_index_sha256']);PERFORM maezo_d7_control._fields(proof);PERFORM maezo_d7_control._need(proof->>'protocol'='maezo.d7-phase-proof.v1');
  logical:=(proof-ARRAY['generation_id','generation_binding_sha256','decision_sha256','purpose','phase','source','tree','image_sha256','config_set_sha256','restore_receipt_sha256','readiness_result_sha256'])||pg_catalog.jsonb_build_object('protocol','maezo.d7-operation-proof.v1','operation',op,'restore_reconciliation_sha256',proof->'restore_receipt_sha256');PERFORM maezo_d7_control._proof(logical,op,f);
 ELSIF op='reconcile_fence' THEN
  PERFORM maezo_d7_control._keys(body,ARRAY['operation','mode','database_binding','expected_owner','successor_owner','claim_id','claim_receipt_sha256','next_generation_id','retired_generation_index_sha256']);PERFORM maezo_d7_control._fields(body);PERFORM maezo_d7_control._typed(body->'database_binding','DatabaseBinding');
  PERFORM maezo_d7_control._keys(proof,ARRAY['protocol','operation_proof','owner_subject','owner_lineage_bytes','owner_lineage_sha256','old_fence_owner_sha256','restore_reconciliation_bytes','restore_reconciliation_sha256']);PERFORM maezo_d7_control._fields(proof);PERFORM maezo_d7_control._need(proof->>'protocol'='maezo.d7-owner-handoff-proof.v1');
  PERFORM maezo_d7_control._proof(proof->'operation_proof',op,f,successor);wire:=maezo_d7_control._unb64(proof->>'owner_lineage_bytes');PERFORM maezo_d7_control._need(maezo_d7_control._sha(wire)=proof->>'owner_lineage_sha256');lineage:=maezo_d7_control.decode_owner_lineage_wire(wire);root:=maezo_d7_control._wire(maezo_d7_control._unb64(lineage->>'root_bytes'));
  PERFORM maezo_d7_control._owner(body->'successor_owner');PERFORM maezo_d7_control._need(body->'successor_owner'=pg_catalog.jsonb_build_object('owner_subject',root->'owner_subject','run_id',root->'run_id','epoch',root->'epoch') AND proof->'owner_subject'=root->'owner_subject' AND q->'run_id'=root->'run_id' AND q->'epoch'=root->'epoch' AND q->'scope'=root->'scope','P7D04');
  PERFORM maezo_d7_control._need(proof->'operation_proof'->'scope'=root->'scope' AND proof->'operation_proof'->'run_id'=root->'run_id' AND proof->'operation_proof'->'epoch'=root->'epoch' AND proof->'operation_proof'->'journal_revision'=root->'journal_revision' AND proof->'operation_proof'->'pending_index_sha256'=root->'pending_index_sha256','P7D04');
  PERFORM maezo_d7_control._need(maezo_d7_control._now_ms()<(lineage->>'deadline_ms')::bigint,'P7D09');
  PERFORM maezo_d7_control._keys(body->'expected_owner',ARRAY['owner_subject','run_id','epoch','revision','controller_revision','database_binding_sha256','next_generation_id','current_generation_id']);PERFORM maezo_d7_control._fields(body->'expected_owner');PERFORM maezo_d7_control._need(proof->>'old_fence_owner_sha256'=maezo_d7_control._sha(maezo_d7_control._canonical(body->'expected_owner')));
  IF successor THEN claim:=maezo_d7_control._wire(maezo_d7_control._unb64(lineage->>'claim_receipt_bytes'));PERFORM maezo_d7_control._need(claim->'claim_id'=body->'claim_id' AND lineage->'claim_receipt_sha256'=body->'claim_receipt_sha256' AND (root->>'epoch')::bigint>(body->'expected_owner'->>'epoch')::bigint,'P7D04');
   IF pg_catalog.jsonb_array_length(lineage->'ancestor_claim_bytes')>0 THEN old_owner:=maezo_d7_control._wire(maezo_d7_control._unb64(lineage->'ancestor_claim_bytes'->>0))->'previous_owner';ELSE old_owner:=claim->'previous_owner';END IF;
   PERFORM maezo_d7_control._need(old_owner=pg_catalog.jsonb_build_object('owner_subject',body->'expected_owner'->'owner_subject','run_id',body->'expected_owner'->'run_id','epoch',body->'expected_owner'->'epoch'),'P7D04');
  ELSE PERFORM maezo_d7_control._need(body->'claim_id'='null'::jsonb AND body->'claim_receipt_sha256'='null'::jsonb AND body->'successor_owner'=pg_catalog.jsonb_build_object('owner_subject',f.owner_subject,'run_id',f.owner_run_id,'epoch',f.epoch),'P7D04');END IF;
  PERFORM maezo_d7_control._need(body->>'mode' IN ('same_incarnation_successor','current_owner_reconcile','database_restore'));
  IF body->>'mode'='database_restore' THEN wire:=maezo_d7_control._unb64(proof->>'restore_reconciliation_bytes');PERFORM maezo_d7_control._need(maezo_d7_control._sha(wire)=proof->>'restore_reconciliation_sha256');restore:=maezo_d7_control.decode_owner_restore_wire(wire);
   PERFORM maezo_d7_control._need(restore->'scope'=q->'scope' AND restore->'run_id'=q->'run_id' AND restore->'epoch'=q->'epoch' AND restore->'owner_subject'=proof->'owner_subject' AND restore->'new_database_binding'=body->'database_binding' AND restore->'old_database_binding'=maezo_d7_control._wire(f.database_binding_bytes) AND restore->'controller_table_identity_sha256'=lineage->'table_identity_sha256','P7D02');
  ELSE
   PERFORM maezo_d7_control._need(proof->'restore_reconciliation_bytes'='null'::jsonb AND proof->'restore_reconciliation_sha256'='null'::jsonb AND body->'database_binding'=maezo_d7_control._wire(f.database_binding_bytes),'P7D02');
   IF f.restore_state='RECONCILED' AND root->>'restore_state'='RECONCILED' THEN NULL;
   ELSE
    -- Empty installation origin only. The current qualified issuer authenticates
    -- complete control/closure observations; local catalog and histories also refuse.
    PERFORM maezo_d7_control._need(body->>'mode'='current_owner_reconcile' AND f.restore_state IN ('UNRECONCILED','RECONCILED') AND root->>'restore_state'='UNRECONCILED' AND root->>'state'='REVIEWED' AND root->'epoch'='1'::jsonb AND root->'revision'='1'::jsonb AND root->'next_generation_id'='1'::jsonb AND root->'db_fence_epoch'='0'::jsonb AND root->'journal_revision'='0'::jsonb AND root->'pending_operation_ids'='[]'::jsonb AND root->'current_owner_claim_sha256'='null'::jsonb AND root->'current_generation_id'='null'::jsonb AND root->'activation_decision_sha256'='null'::jsonb AND root->'restore_receipt_sha256'='null'::jsonb AND root->'readiness_result_sha256'='null'::jsonb AND lineage->'claim_receipt_bytes'='null'::jsonb AND lineage->'ancestor_claim_bytes'='[]'::jsonb,'P7D02');
    PERFORM maezo_d7_control._need(f.epoch=1 AND ((f.revision=1 AND f.mode='CLOSED' AND f.restore_state='UNRECONCILED') OR (f.restore_state='RECONCILED' AND EXISTS(SELECT 1 FROM maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT" i WHERE i.issuer_operation_id=(q->>'issuer_operation_id')::uuid AND i.operation='reconcile_fence' AND i.request_bytes=maezo_d7_control._canonical(q-'proof')))) AND f.next_generation_id=1 AND f.current_generation_id IS NULL AND body->'next_generation_id'='1'::jsonb,'P7D02');
    PERFORM maezo_d7_control._need(root->>'pending_index_sha256'=maezo_d7_control._sha(maezo_d7_control._canonical('[]'::jsonb)) AND root->'managed_registry_sha256'=root->'pending_index_sha256' AND root->'retired_index_sha256'=root->'pending_index_sha256','P7D02');
