  IF body->>'permit_purpose'<>'receipt_read' THEN PERFORM maezo_d7_control._need(f.mode='CLOSED' AND f.current_generation_id IS NULL AND proof->>'pending_index_sha256'=maezo_d7_control._sha(maezo_d7_control._canonical('[]'::jsonb)) AND proof->'settled_journal_sha256'<>'null'::jsonb AND proof->'restore_reconciliation_sha256'<>'null'::jsonb,'P7D10');END IF;
  IF body->'principal_origin'->>'kind'='owner_prepared_one_shot' THEN
  SELECT * INTO birth FROM maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT" WHERE event='PREPARED' AND preparation_id=(body->'principal_origin'->>'preparation_id')::uuid AND login_oid=(body->>'login_oid')::oid AND login_name=body->>'login_name';PERFORM maezo_d7_control._need(FOUND,'P7D09');owner_result:=maezo_d7_control._wire(birth.result_bytes);
  PERFORM maezo_d7_control._need(owner_result->'principal'->>'kind'='one_shot' AND owner_result->'principal'->'purpose'=body->'permit_purpose' AND birth.tenant=f.tenant AND birth.environment=f.environment AND birth.engine_name=f.engine_name AND NOT EXISTS(SELECT 1 FROM maezo_d7_control."MZO_PROVISIONING_PERMIT" WHERE login_oid=birth.login_oid) AND NOT EXISTS(SELECT 1 FROM maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT" WHERE preparation_id=birth.preparation_id AND event='REMOVED'),'P7D09');
  PERFORM maezo_d7_control._login(birth.login_oid,birth.login_name,true);
  ELSE
   PERFORM maezo_d7_control._need(NOT EXISTS(SELECT 1 FROM maezo_d7_control."MZO_PROVISIONING_PERMIT" x WHERE x.tenant=f.tenant AND x.environment=f.environment AND x.engine_name=f.engine_name AND x.login_oid=(body->>'login_oid')::oid AND x.state='ISSUED' AND x.principal_origin->>'kind'='installation_receipt_reader'),'P7D06');
  END IF;
  INSERT INTO maezo_d7_control."MZO_PROVISIONING_PERMIT"(tenant,environment,engine_name,permit_id,database_incarnation,epoch,run_id,request_sha256,operation,purpose,login_oid,login_name,controller_task_identity_sha256,issuer_login_oid,issuer_subject,trust_profile_sha256,control_observation_sha256,database_observation_sha256,issued_at_ms,deadline_ms,state,revision,native_transaction_deadline_ms,owner_preparation_id,principal_origin)
  VALUES(f.tenant,f.environment,f.engine_name,(body->>'permit_id')::uuid,f.database_incarnation,f.epoch,f.owner_run_id,body->>'logical_request_sha256',body->>'native_operation',body->>'permit_purpose',(body->>'login_oid')::oid,body->>'login_name',body->>'controller_task_identity_sha256',issuer_oid,SESSION_USER,f.trust_profile_sha256,proof->>'control_observation_sha256',proof->>'database_observation_sha256',now_ms,LEAST(now_ms+60000,(proof->>'controller_lease_deadline_ms')::bigint,(proof->>'observation_deadline_ms')::bigint),'ISSUED',1,LEAST(now_ms+30000,(proof->>'controller_lease_deadline_ms')::bigint),birth.preparation_id,body->'principal_origin') RETURNING * INTO p;
 ELSIF op='revoke_permit' THEN
  PERFORM maezo_d7_control._keys(body,ARRAY['operation','permit_id','reason']);PERFORM maezo_d7_control._fields(body);PERFORM maezo_d7_control._typed(body->'reason','RefusalCode');SELECT * INTO p FROM maezo_d7_control."MZO_PROVISIONING_PERMIT" WHERE tenant=f.tenant AND environment=f.environment AND engine_name=f.engine_name AND permit_id=(body->>'permit_id')::uuid FOR UPDATE;PERFORM maezo_d7_control._need(FOUND,'P7D07');
  IF p.state<>'REVOKED' THEN IF p.principal_origin->>'kind'='owner_prepared_one_shot' THEN PERFORM maezo_d7_control._login(p.login_oid,p.login_name,false);END IF;UPDATE maezo_d7_control."MZO_PROVISIONING_PERMIT" SET state='REVOKED',revision=revision+1,revoked_at_ms=now_ms,revocation_reason=body->>'reason',revoked_by_issuer_operation_id=(q->>'issuer_operation_id')::uuid WHERE permit_id=p.permit_id RETURNING * INTO p;END IF;
 ELSE PERFORM maezo_d7_control._need(false,'P7D11');END IF;
 UPDATE maezo_d7_control."MZO_PROVISIONING_FENCE" SET revision=revision+1,updated_at_ms=now_ms WHERE tenant=f.tenant AND environment=f.environment AND engine_name=f.engine_name RETURNING * INTO f;
 IF gen_op THEN result:=pg_catalog.jsonb_build_object('protocol','maezo.provisioning-issuer-receipt.v1','scope',q->'scope','issuer_operation_id',q->'issuer_operation_id','request_sha256',request_hash,'epoch',q->'epoch','generation_id',gid,'purpose',g.purpose,'binding_sha256',g.generation_binding_sha256,'activation_decision_sha256',g.activation_decision_sha256,'status',g.status,'revision',g.revision,'issuer_login_oid',issuer_oid::bigint,'issuer_session_user',SESSION_USER,'issuer_current_user',CURRENT_USER,'recorded_before_commit_at_ms',now_ms,'provisioning_schema_version',1);
 ELSE state:=CASE WHEN op IN ('issue_permit','revoke_permit') THEN p.state ELSE f.mode END;result:=pg_catalog.jsonb_build_object('protocol','maezo.d7-store-transition-receipt.v1','scope',q->'scope','run_id',q->'run_id','epoch',q->'epoch','issuer_operation_id',q->'issuer_operation_id','operation',op,'request_sha256',request_hash,'fence_revision',f.revision,'generation_id',gid,'permit_id',CASE WHEN op IN ('issue_permit','revoke_permit') THEN p.permit_id ELSE NULL END,'state',state,'issuer_session_user',SESSION_USER,'issuer_login_oid',issuer_oid::bigint,'issuer_current_user',CURRENT_USER,'issuer_definer_oid',definer_oid::bigint,'recorded_before_commit_at_ms',now_ms,'provisioning_schema_version',1);END IF;
 result_wire:=maezo_d7_control._canonical(result);
 INSERT INTO maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT"(tenant,environment,engine_name,issuer_operation_id,operation,request_sha256,request_bytes,result_sha256,result_bytes,epoch,generation_id,database_incarnation,issuer_session_user,issuer_login_oid,issuer_current_user,issuer_definer_oid,recorded_before_commit_at_ms,schema_version)
 VALUES(f.tenant,f.environment,f.engine_name,(q->>'issuer_operation_id')::uuid,op,request_hash,request_wire,maezo_d7_control._sha(result_wire),result_wire,(q->>'epoch')::bigint,gid,f.database_incarnation,SESSION_USER,issuer_oid,CURRENT_USER,definer_oid,now_ms,1);
 -- Freshness is checked again after locks, catalog mutation and receipt construction.
 IF op='reconcile_fence' THEN PERFORM maezo_d7_control._proof(proof->'operation_proof',op,f);ELSIF op='record_current_proof' THEN PERFORM maezo_d7_control._proof(logical,op,f);ELSE PERFORM maezo_d7_control._proof(proof,op,f);END IF;
 PERFORM maezo_d7_control._assert_catalog();RETURN pg_catalog.jsonb_build_object('protocol','maezo.d7-store-result.v1','issuer_operation_id',q->'issuer_operation_id','request_sha256',request_hash,'result_sha256',maezo_d7_control._sha(result_wire),'canonical_result_bytes',maezo_d7_control._b64(result_wire));
END $d7$;

CREATE FUNCTION maezo_d7_control.lock_runtime_v2_scope(q pg_catalog.jsonb) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE f maezo_d7_control."MZO_PROVISIONING_FENCE";g maezo_d7_control."MZO_RUNTIME_ADMISSION";s jsonb;proof jsonb;result jsonb;now_ms bigint;retiring boolean;actor oid;k text;
BEGIN
 PERFORM maezo_d7_control._identity('D guard-function owner',NULL);
 PERFORM maezo_d7_control._keys(q,ARRAY['protocol','account','region','tenant','environment','engine_name','database_incarnation','database_binding_sha256','runtime_generation','epoch','decision_digest','purpose','admission_phase','action']);
 PERFORM maezo_d7_control._need(pg_catalog.octet_length(q::text)<=16384 AND q->>'protocol'='maezo.d7-native-guard-request.v1');
 s:=q-ARRAY['protocol','database_incarnation','database_binding_sha256','runtime_generation','epoch','decision_digest','purpose','admission_phase','action'];PERFORM maezo_d7_control._typed(q->'account','Account');PERFORM maezo_d7_control._typed(q->'region','Region');PERFORM maezo_d7_control._typed(q->'tenant','Id');PERFORM maezo_d7_control._typed(q->'environment','Id');PERFORM maezo_d7_control._typed(q->'engine_name','Id');
 PERFORM maezo_d7_control._typed(q->'database_incarnation','Uuid');PERFORM maezo_d7_control._typed(q->'database_binding_sha256','Sha256');PERFORM maezo_d7_control._typed(q->'runtime_generation','Positive');PERFORM maezo_d7_control._typed(q->'epoch','Positive');PERFORM maezo_d7_control._typed(q->'decision_digest','Sha256');
 PERFORM maezo_d7_control._need(q->>'purpose' IN ('candidate','runtime') AND q->>'admission_phase' IN ('ACTIVE','CANDIDATE_QUALIFICATION','RESTORE_QUALIFICATION','RETIREMENT') AND q->>'action' IN ('native_guard','native_register','native_refresh','native_retire','native_history'));
 SELECT * INTO f FROM maezo_d7_control."MZO_PROVISIONING_FENCE" WHERE tenant=q->>'tenant' AND environment=q->>'environment' AND engine_name=q->>'engine_name' FOR UPDATE;
 PERFORM maezo_d7_control._need(FOUND,'P7D02');PERFORM maezo_d7_control._database(f);s:=s||pg_catalog.jsonb_build_object('database_binding',maezo_d7_control._wire(f.database_binding_bytes));PERFORM maezo_d7_control._typed(s,'Scope');
 PERFORM maezo_d7_control._need(f.account=q->>'account' AND f.region=q->>'region' AND f.database_incarnation::text=q->>'database_incarnation' AND f.database_binding_sha256=q->>'database_binding_sha256','P7D02');
 PERFORM maezo_d7_control._need(f.epoch=(q->>'epoch')::bigint,'P7D04');PERFORM maezo_d7_control._need(f.restore_state='RECONCILED','P7D09');
 SELECT * INTO g FROM maezo_d7_control."MZO_RUNTIME_ADMISSION" WHERE tenant=f.tenant AND environment=f.environment AND engine_name=f.engine_name AND generation_id=(q->>'runtime_generation')::bigint FOR UPDATE;
 PERFORM maezo_d7_control._need(FOUND,'P7D05');PERFORM maezo_d7_control._assert_catalog();
 PERFORM maezo_d7_control._need(g.account=f.account AND g.region=f.region AND g.database_incarnation=f.database_incarnation AND g.database_binding_sha256=f.database_binding_sha256,'P7D02');
 PERFORM maezo_d7_control._need(g.activation_decision_sha256=q->>'decision_digest' AND g.purpose=q->>'purpose','P7D03');
 PERFORM maezo_d7_control._need(maezo_d7_control._sha(g.generation_core_bytes)=g.generation_binding_sha256 AND maezo_d7_control._sha(g.activation_decision_bytes)=g.activation_decision_sha256,'P7D09');
 actor:=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=SESSION_USER);retiring:=q->>'action'='native_retire';
 IF q->>'action' IN ('native_register','native_refresh','native_retire') THEN PERFORM maezo_d7_control._need(actor=maezo_d7_control._role('actual issuer login'),'P7D01');
 ELSE PERFORM maezo_d7_control._need(actor=g.login_oid AND SESSION_USER=g.login_name,'P7D01');END IF;
 IF retiring THEN
  -- Historical retirement closes native state only. It conveys no admission or quiescence.
  PERFORM maezo_d7_control._need(q->>'admission_phase'='RETIREMENT' AND g.status='RETIRED' AND g.generation_epoch<=f.epoch AND f.current_generation_id IS DISTINCT FROM g.generation_id,'P7D05');
 ELSE
  PERFORM maezo_d7_control._need(g.status='OPEN' AND f.current_generation_id=g.generation_id AND g.generation_epoch=f.epoch AND g.run_id=f.owner_run_id,'P7D05');
  PERFORM maezo_d7_control._need(g.phase=q->>'admission_phase' AND g.phase<>'RETIREMENT','P7D03');
  IF g.phase='ACTIVE' THEN PERFORM maezo_d7_control._need(g.purpose='runtime' AND f.mode='OPEN' AND f.controller_state='ACTIVE' AND g.readiness_result_sha256 IS NOT NULL,'P7D03');
  ELSIF g.phase='CANDIDATE_QUALIFICATION' THEN PERFORM maezo_d7_control._need(g.purpose='candidate' AND f.mode='CANDIDATE' AND f.controller_state IN ('CANDIDATE_ADMITTED','CANDIDATE_VALIDATED') AND g.readiness_result_sha256 IS NULL,'P7D03');
  ELSIF g.phase='RESTORE_QUALIFICATION' THEN PERFORM maezo_d7_control._need(g.purpose='runtime' AND f.mode='RESTORING' AND f.controller_state IN ('RESTORING','READINESS_VERIFIED') AND g.readiness_result_sha256 IS NULL,'P7D03');
  ELSE PERFORM maezo_d7_control._need(false,'P7D03');END IF;
  PERFORM maezo_d7_control._need(g.phase_proof_bytes IS NOT NULL AND maezo_d7_control._sha(g.phase_proof_bytes)=g.phase_proof_sha256,'P7D09');proof:=maezo_d7_control._wire(g.phase_proof_bytes);
  PERFORM maezo_d7_control._need(proof->'scope'=s AND proof->>'run_id'=f.owner_run_id::text AND (proof->>'epoch')::bigint=f.epoch AND (proof->>'generation_id')::bigint=g.generation_id AND proof->>'generation_binding_sha256'=g.generation_binding_sha256 AND proof->>'decision_sha256'=g.activation_decision_sha256 AND proof->>'phase'=g.phase AND proof->>'trust_profile_sha256'=f.trust_profile_sha256,'P7D09');
  PERFORM maezo_d7_control._need(g.observation_pair_sha256=f.observation_pair_sha256 AND g.observation_deadline_ms=f.observation_deadline_ms AND g.journal_revision=f.journal_revision AND g.settled_journal_sha256=f.settled_journal_sha256 AND f.pending_index_sha256=maezo_d7_control._sha(maezo_d7_control._canonical('[]'::jsonb)),'P7D10');
  PERFORM maezo_d7_control._need(EXISTS(SELECT 1 FROM maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT" r WHERE r.issuer_operation_id=g.proof_issuer_operation_id AND r.operation='record_current_proof' AND r.epoch=f.epoch AND r.tenant=f.tenant AND r.environment=f.environment AND r.engine_name=f.engine_name),'P7D09');
  PERFORM maezo_d7_control._need(EXISTS(SELECT 1 FROM maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT" r WHERE r.result_sha256=g.restore_receipt_sha256 AND r.operation IN ('open_runtime_generation','admit_candidate_login') AND r.generation_id=g.generation_id AND r.epoch=f.epoch AND r.tenant=f.tenant AND r.environment=f.environment AND r.engine_name=f.engine_name),'P7D09');
 END IF;
 -- The returned deadline is captured here. A later refresh cannot extend a caller's copy.
 now_ms:=maezo_d7_control._now_ms();
 IF NOT retiring THEN PERFORM maezo_d7_control._need(f.observed_at_ms<=now_ms AND now_ms<LEAST(g.valid_until_ms,g.observation_deadline_ms,f.controller_lease_deadline_ms) AND g.valid_until_ms IS NOT NULL AND g.observation_deadline_ms IS NOT NULL AND f.controller_lease_deadline_ms IS NOT NULL,'P7D09');END IF;
 result:=(q-'action')||pg_catalog.jsonb_build_object('protocol','maezo.d7-native-guard-result.v1','generation_epoch',g.generation_epoch,'fence_revision',f.revision,'generation_revision',g.revision,'login_name',g.login_name,'login_oid',g.login_oid::bigint,'generation_binding_digest',g.generation_binding_sha256,'trust_profile_digest',f.trust_profile_sha256,'database_clock_ms',now_ms,
 'valid_until',CASE WHEN retiring THEN NULL ELSE g.valid_until_ms END,'observation_digest',CASE WHEN retiring THEN NULL ELSE g.observation_pair_sha256 END,'observation_deadline',CASE WHEN retiring THEN NULL ELSE g.observation_deadline_ms END,'restore_receipt_digest',CASE WHEN retiring THEN NULL ELSE g.restore_receipt_sha256 END,'readiness_digest',CASE WHEN retiring THEN NULL ELSE g.readiness_result_sha256 END,'journal_revision',CASE WHEN retiring THEN NULL ELSE g.journal_revision END,'journal_digest',CASE WHEN retiring THEN NULL ELSE g.settled_journal_sha256 END,'admission_proof_digest',CASE WHEN retiring THEN NULL ELSE g.phase_proof_sha256 END);
 RETURN result;
EXCEPTION WHEN SQLSTATE 'P7D01' OR SQLSTATE 'P7D02' OR SQLSTATE 'P7D03' OR SQLSTATE 'P7D04' OR SQLSTATE 'P7D05' OR SQLSTATE 'P7D06' OR SQLSTATE 'P7D07' OR SQLSTATE 'P7D08' OR SQLSTATE 'P7D09' OR SQLSTATE 'P7D10' OR SQLSTATE 'P7D11' THEN RAISE;
 WHEN OTHERS THEN PERFORM maezo_d7_control._need(false,'P7D09');RETURN NULL;
END $d7$;
CREATE FUNCTION maezo_d7_control.lock_provisioning_scope(q pg_catalog.jsonb) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE f maezo_d7_control."MZO_PROVISIONING_FENCE";p maezo_d7_control."MZO_PROVISIONING_PERMIT";birth maezo_d7_control."MZO_OWNER_PREPARATION_RECEIPT";b jsonb;now_ms bigint;native_actor text;
BEGIN
 PERFORM maezo_d7_control._identity('D guard-function owner',NULL);PERFORM maezo_d7_control._keys(q,ARRAY['protocol','scope','run_id','epoch','permit_id','request_sha256','operation','purpose']);PERFORM maezo_d7_control._fields(q);PERFORM maezo_d7_control._typed(q->'scope','Scope');
 PERFORM maezo_d7_control._need(q->>'protocol'='maezo.d7-provisioning-guard.v1' AND q->>'operation' IN ('deploy','grant','receipt') AND q->>'purpose'=CASE q->>'operation' WHEN 'receipt' THEN 'receipt_read' ELSE q->>'operation' END);
 SELECT * INTO f FROM maezo_d7_control."MZO_PROVISIONING_FENCE" WHERE tenant=q->'scope'->>'tenant' AND environment=q->'scope'->>'environment' AND engine_name=q->'scope'->>'engine_name' FOR UPDATE;
 PERFORM maezo_d7_control._need(FOUND,'P7D02');PERFORM maezo_d7_control._database(f);PERFORM maezo_d7_control._need(f.account=q->'scope'->>'account' AND f.region=q->'scope'->>'region','P7D02');
 PERFORM maezo_d7_control._need(f.epoch=(q->>'epoch')::bigint AND f.owner_run_id::text=q->>'run_id','P7D04');
 SELECT * INTO p FROM maezo_d7_control."MZO_PROVISIONING_PERMIT" WHERE tenant=f.tenant AND environment=f.environment AND engine_name=f.engine_name AND permit_id=(q->>'permit_id')::uuid FOR UPDATE;
 PERFORM maezo_d7_control._need(FOUND,'P7D01');PERFORM maezo_d7_control._assert_catalog();
 PERFORM maezo_d7_control._need(SESSION_USER=p.login_name AND (SELECT oid FROM pg_catalog.pg_roles WHERE rolname=SESSION_USER)=p.login_oid,'P7D01');
 PERFORM maezo_d7_control._need(p.state='ISSUED' AND p.database_incarnation=f.database_incarnation AND p.epoch=f.epoch AND p.run_id=f.owner_run_id AND p.request_sha256=q->>'request_sha256' AND p.operation=q->>'operation' AND p.purpose=q->>'purpose','P7D07');
 native_actor:=maezo_d7_control._permit_origin(p.principal_origin,p.login_name,p.login_oid,p.operation,p.purpose,q->'scope');
 PERFORM maezo_d7_control._need(q->'scope'->'database_binding'=maezo_d7_control._wire(f.database_binding_bytes),'P7D02');
 IF p.purpose<>'receipt_read' THEN PERFORM maezo_d7_control._need(f.mode='CLOSED' AND f.current_generation_id IS NULL AND f.restore_state='RECONCILED' AND f.pending_index_sha256=maezo_d7_control._sha(maezo_d7_control._canonical('[]'::jsonb)) AND f.restore_reconciliation_sha256 IS NOT NULL,'P7D10');END IF;
 now_ms:=maezo_d7_control._now_ms();PERFORM maezo_d7_control._need(f.restore_state='RECONCILED' AND p.issued_at_ms<=now_ms AND now_ms<LEAST(p.deadline_ms,p.native_transaction_deadline_ms) AND p.trust_profile_sha256=f.trust_profile_sha256,'P7D09');
 RETURN q||pg_catalog.jsonb_build_object('protocol','maezo.d7-provisioning-guard-result.v1','permit_revision',p.revision,'login_name',p.login_name,'login_oid',p.login_oid::bigint,'native_actor',native_actor,'deadline_ms',p.deadline_ms,'native_transaction_deadline_ms',p.native_transaction_deadline_ms,'database_clock_ms',now_ms);
EXCEPTION WHEN SQLSTATE 'P7D01' OR SQLSTATE 'P7D02' OR SQLSTATE 'P7D03' OR SQLSTATE 'P7D04' OR SQLSTATE 'P7D05' OR SQLSTATE 'P7D06' OR SQLSTATE 'P7D07' OR SQLSTATE 'P7D08' OR SQLSTATE 'P7D09' OR SQLSTATE 'P7D10' OR SQLSTATE 'P7D11' THEN RAISE;
 WHEN OTHERS THEN PERFORM maezo_d7_control._need(false,'P7D09');RETURN NULL;
END $d7$;
CREATE FUNCTION maezo_d7_control.read_provisioning_receipt(q pg_catalog.jsonb) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE guard jsonb;k jsonb;r maezo_d7_control."MZO_PROVISIONING_RECEIPT";
BEGIN
 PERFORM maezo_d7_control._identity('D guard-function owner',NULL);PERFORM maezo_d7_control._keys(q,ARRAY['protocol','guard','receipt_key','request_sha256']);PERFORM maezo_d7_control._need(q->>'protocol'='maezo.d7-provisioning-receipt-read.v1');PERFORM maezo_d7_control._typed(q->'receipt_key','ReceiptKey');PERFORM maezo_d7_control._typed(q->'request_sha256','Sha256');
 guard:=maezo_d7_control.lock_provisioning_scope(q->'guard');k:=q->'receipt_key';
 PERFORM maezo_d7_control._need(k->>'tenant'=guard->'scope'->>'tenant' AND k->>'environment'=guard->'scope'->>'environment' AND k->>'engine_name'=guard->'scope'->>'engine_name','P7D02');
 IF guard->>'purpose'='receipt_read' THEN PERFORM maezo_d7_control._need(guard->>'request_sha256'=maezo_d7_control._sha(maezo_d7_control._canonical(pg_catalog.jsonb_build_object('receipt_key',k,'request_sha256',q->'request_sha256'))),'P7D06');
 ELSE PERFORM maezo_d7_control._need(guard->>'request_sha256'=q->>'request_sha256' AND k->>'operation'=guard->>'operation' AND k->>'run_id'=guard->>'run_id','P7D06');END IF;
 SELECT * INTO r FROM maezo_d7_control."MZO_PROVISIONING_RECEIPT" WHERE tenant=k->>'tenant' AND environment=k->>'environment' AND engine_name=k->>'engine_name' AND operation=k->>'operation' AND run_id=(k->>'run_id')::uuid;
 IF NOT FOUND THEN PERFORM maezo_d7_control.lock_provisioning_scope(q->'guard');RETURN pg_catalog.jsonb_build_object('kind','NOT_FOUND','receipt_key',k);END IF;
 PERFORM maezo_d7_control._need(r.request_sha256=q->>'request_sha256','P7D06');PERFORM maezo_d7_control._need(maezo_d7_control._sha(r.canonical_result_bytes)=r.result_sha256 AND maezo_d7_control._sha(r.receipt_bytes)=r.receipt_sha256,'P7D09');
 PERFORM maezo_d7_control._need(maezo_d7_control._now_ms()<LEAST((guard->>'deadline_ms')::bigint,(guard->>'native_transaction_deadline_ms')::bigint),'P7D09');
 RETURN pg_catalog.jsonb_build_object('kind','FOUND','receipt_key',k,'request_sha256',r.request_sha256,'canonical_result_bytes',maezo_d7_control._b64(r.canonical_result_bytes),'result_sha256',r.result_sha256);
EXCEPTION WHEN SQLSTATE 'P7D01' OR SQLSTATE 'P7D02' OR SQLSTATE 'P7D03' OR SQLSTATE 'P7D04' OR SQLSTATE 'P7D05' OR SQLSTATE 'P7D06' OR SQLSTATE 'P7D07' OR SQLSTATE 'P7D08' OR SQLSTATE 'P7D09' OR SQLSTATE 'P7D10' OR SQLSTATE 'P7D11' THEN RAISE;
 WHEN OTHERS THEN PERFORM maezo_d7_control._need(false,'P7D09');RETURN NULL;
END $d7$;
CREATE FUNCTION maezo_d7_control.append_provisioning_receipt(q pg_catalog.jsonb) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE guard jsonb;n jsonb;k jsonb;body jsonb;wire bytea;result_wire bytea;r maezo_d7_control."MZO_PROVISIONING_RECEIPT";inc uuid;
BEGIN
 PERFORM maezo_d7_control._need((SELECT oid FROM pg_catalog.pg_roles WHERE rolname=CURRENT_USER)=(SELECT proowner FROM pg_catalog.pg_proc WHERE oid='maezo_d7_control.append_provisioning_receipt(jsonb)'::pg_catalog.regprocedure),'P7D01');PERFORM maezo_d7_control._keys(q,ARRAY['protocol','guard','native_receipt_bytes','native_receipt_sha256']);PERFORM maezo_d7_control._need(q->>'protocol'='maezo.d7-provisioning-receipt-append.v1');
 wire:=maezo_d7_control._unb64(q->>'native_receipt_bytes');PERFORM maezo_d7_control._need(maezo_d7_control._sha(wire)=q->>'native_receipt_sha256');n:=maezo_d7_control._wire(wire);PERFORM maezo_d7_control._typed(n,'NativeReceipt');
 guard:=maezo_d7_control.lock_provisioning_scope(q->'guard');PERFORM maezo_d7_control._need(guard->>'purpose' IN ('deploy','grant'),'P7D03');k:=n->'receipt_key';
 PERFORM maezo_d7_control._need(n->'scope'=guard->'scope' AND k->>'tenant'=guard->'scope'->>'tenant' AND k->>'environment'=guard->'scope'->>'environment' AND k->>'engine_name'=guard->'scope'->>'engine_name' AND k->>'run_id'=guard->>'run_id' AND k->>'operation'=guard->>'operation','P7D02');
 PERFORM maezo_d7_control._need(n->>'request_sha256'=guard->>'request_sha256' AND n->>'permit_id'=guard->>'permit_id' AND n->'commit_epoch'=guard->'epoch' AND n->'native_actor'->>'login_name'=guard->>'login_name' AND n->'native_actor'->>'session_user'=SESSION_USER AND n->'native_actor'->>'current_user'=SESSION_USER AND n->'native_actor'->'login_oid'=guard->'login_oid' AND n->'native_actor'->>'purpose'=guard->>'operation','P7D01');
 result_wire:=maezo_d7_control._unb64(n->>'canonical_result_bytes');PERFORM maezo_d7_control._need(maezo_d7_control._sha(result_wire)=n->>'result_sha256');body:=maezo_d7_control._wire(result_wire);PERFORM maezo_d7_control._typed(body,CASE k->>'operation' WHEN 'deploy' THEN 'DeployResultBody' ELSE 'GrantResultBody' END);
 PERFORM maezo_d7_control._need(body->'operation'=k->'operation','P7D03');IF k->>'operation'='deploy' THEN PERFORM maezo_d7_control._need(body->'tenant'=n->'scope'->'tenant','P7D02');ELSE PERFORM maezo_d7_control._need(body->'deployment_receipt'->'receipt_key'->'tenant'=n->'scope'->'tenant' AND body->'deployment_receipt'->'receipt_key'->'environment'=n->'scope'->'environment' AND body->'deployment_receipt'->'receipt_key'->'engine_name'=n->'scope'->'engine_name','P7D02');END IF;
 SELECT * INTO r FROM maezo_d7_control."MZO_PROVISIONING_RECEIPT" WHERE tenant=k->>'tenant' AND environment=k->>'environment' AND engine_name=k->>'engine_name' AND operation=k->>'operation' AND run_id=(k->>'run_id')::uuid;
 IF FOUND THEN PERFORM maezo_d7_control._need(r.request_sha256=n->>'request_sha256' AND r.receipt_bytes=wire AND r.result_sha256=n->>'result_sha256','P7D06');PERFORM maezo_d7_control.lock_provisioning_scope(q->'guard');RETURN maezo_d7_control._wire(r.receipt_bytes);END IF;
 inc:=maezo_d7_control._receipt_incarnation(q->'guard');
 PERFORM maezo_d7_control._need((n->>'recorded_before_commit_at_ms')::bigint>=(guard->>'database_clock_ms')::bigint-30000 AND (n->>'recorded_before_commit_at_ms')::bigint<=maezo_d7_control._now_ms());
 INSERT INTO maezo_d7_control."MZO_PROVISIONING_RECEIPT"(tenant,environment,engine_name,operation,run_id,request_sha256,result_sha256,canonical_result_bytes,source,tree,native_image_sha256,native_jar_sha256,trust_profile_sha256,database_incarnation,permit_id,epoch,native_actor,native_login_oid,recorded_before_commit_at_ms,schema_version,receipt_bytes,receipt_sha256)
 VALUES(k->>'tenant',k->>'environment',k->>'engine_name',k->>'operation',(k->>'run_id')::uuid,n->>'request_sha256',n->>'result_sha256',result_wire,n->>'source',n->>'tree',n->>'image_sha256',n->>'jar_sha256',n->>'trust_profile_sha256',inc,(n->>'permit_id')::uuid,(n->>'commit_epoch')::bigint,guard->>'native_actor',(guard->>'login_oid')::oid,(n->>'recorded_before_commit_at_ms')::bigint,1,wire,maezo_d7_control._sha(wire));
 PERFORM maezo_d7_control._need(maezo_d7_control._now_ms()<LEAST((guard->>'deadline_ms')::bigint,(guard->>'native_transaction_deadline_ms')::bigint),'P7D09');RETURN n;
EXCEPTION WHEN SQLSTATE 'P7D01' OR SQLSTATE 'P7D02' OR SQLSTATE 'P7D03' OR SQLSTATE 'P7D04' OR SQLSTATE 'P7D05' OR SQLSTATE 'P7D06' OR SQLSTATE 'P7D07' OR SQLSTATE 'P7D08' OR SQLSTATE 'P7D09' OR SQLSTATE 'P7D10' OR SQLSTATE 'P7D11' THEN RAISE;
 WHEN OTHERS THEN PERFORM maezo_d7_control._need(false,'P7D09');RETURN NULL;
END $d7$;
CREATE FUNCTION maezo_d7_control.read_issuer_operation(q pg_catalog.jsonb) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE r maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT";
BEGIN
 PERFORM maezo_d7_control._identity('D guard-function owner',NULL);
 PERFORM maezo_d7_control._need((SELECT oid FROM pg_catalog.pg_roles WHERE rolname=SESSION_USER) IN (maezo_d7_control._role('actual issuer login'),maezo_d7_control._role('scoped D observer login')),'P7D01');
 PERFORM maezo_d7_control._keys(q,ARRAY['protocol','scope','issuer_operation_id','request_sha256','read_guard']);PERFORM maezo_d7_control._need(q->>'protocol'='maezo.d7-issuer-receipt-read.v1');
 PERFORM maezo_d7_control._typed(q->'scope','Scope');PERFORM maezo_d7_control._typed(q->'issuer_operation_id','Uuid');PERFORM maezo_d7_control._typed(q->'request_sha256','Sha256');
 PERFORM maezo_d7_control._need(q->'read_guard'->'scope'=q->'scope' AND q->'read_guard'->>'operation'='receipt' AND q->'read_guard'->>'purpose'='receipt_read' AND q->'read_guard'->>'request_sha256'=maezo_d7_control._sha(maezo_d7_control._canonical(q-ARRAY['protocol','read_guard'])));
 PERFORM maezo_d7_control.lock_provisioning_scope(q->'read_guard');
 SELECT * INTO r FROM maezo_d7_control."MZO_ISSUER_OPERATION_RECEIPT" WHERE issuer_operation_id=(q->>'issuer_operation_id')::uuid;
 IF NOT FOUND THEN PERFORM maezo_d7_control.lock_provisioning_scope(q->'read_guard');RETURN pg_catalog.jsonb_build_object('protocol','maezo.d7-issuer-receipt-read-result.v1','kind','NOT_FOUND','canonical_result_bytes',NULL,'result_sha256',NULL);END IF;
 PERFORM maezo_d7_control._need(r.tenant=q->'scope'->>'tenant' AND r.environment=q->'scope'->>'environment' AND r.engine_name=q->'scope'->>'engine_name' AND r.request_sha256=q->>'request_sha256','P7D06');
 PERFORM maezo_d7_control._need(maezo_d7_control._sha(r.result_bytes)=r.result_sha256,'P7D09');
 PERFORM maezo_d7_control.lock_provisioning_scope(q->'read_guard');
 RETURN pg_catalog.jsonb_build_object('protocol','maezo.d7-issuer-receipt-read-result.v1','kind','FOUND','canonical_result_bytes',maezo_d7_control._b64(r.result_bytes),'result_sha256',r.result_sha256);
EXCEPTION WHEN SQLSTATE 'P7D01' OR SQLSTATE 'P7D02' OR SQLSTATE 'P7D03' OR SQLSTATE 'P7D04' OR SQLSTATE 'P7D05' OR SQLSTATE 'P7D06' OR SQLSTATE 'P7D07' OR SQLSTATE 'P7D08' OR SQLSTATE 'P7D09' OR SQLSTATE 'P7D10' OR SQLSTATE 'P7D11' THEN RAISE;
 WHEN OTHERS THEN PERFORM maezo_d7_control._need(false,'P7D09');RETURN NULL;
END $d7$;

CREATE FUNCTION maezo_d7_control._owner_catalog(roles pg_catalog.jsonb, operational pg_catalog.jsonb, installation pg_catalog.uuid) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE entries jsonb;edges jsonb;grants jsonb;body jsonb;BEGIN
 PERFORM maezo_d7_control._need(pg_catalog.jsonb_typeof(roles)='array' AND pg_catalog.jsonb_array_length(roles) BETWEEN 1 AND 1024);
 PERFORM maezo_d7_control._need(NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(roles) x WHERE (SELECT pg_catalog.count(*) FROM pg_catalog.pg_roles WHERE rolname=x->>'role_name')<>1),'P7D01');
 SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('role_class',x->'role_class','role_name',r.rolname,'role_oid',r.oid::bigint,'rolcanlogin',r.rolcanlogin,'rolsuper',r.rolsuper,'rolcreaterole',r.rolcreaterole,'rolcreatedb',r.rolcreatedb,'rolreplication',r.rolreplication,'rolbypassrls',r.rolbypassrls,'rolinherit',r.rolinherit) ORDER BY x->>'role_class' COLLATE "C",r.rolname COLLATE "C",r.oid) INTO entries FROM pg_catalog.jsonb_array_elements(roles) x JOIN pg_catalog.pg_roles r ON r.rolname=x->>'role_name';
 WITH RECURSIVE related(oid) AS (SELECT (x->>'role_oid')::oid FROM pg_catalog.jsonb_array_elements(entries) x UNION SELECT CASE WHEN a.roleid=r.oid THEN a.member ELSE a.roleid END FROM pg_catalog.pg_auth_members a JOIN related r ON a.roleid=r.oid OR a.member=r.oid)
 SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('role_oid',a.roleid::bigint,'member_oid',a.member::bigint,'grantor_oid',a.grantor::bigint,'admin_option',a.admin_option,'inherit_option',a.inherit_option,'set_option',a.set_option) ORDER BY a.roleid,a.member,a.grantor),'[]'::jsonb) INTO edges FROM pg_catalog.pg_auth_members a WHERE a.roleid IN (SELECT oid FROM related) OR a.member IN (SELECT oid FROM related);
 grants:=maezo_d7_control._grant_catalog(ARRAY(SELECT (x->>'role_oid')::oid FROM pg_catalog.jsonb_array_elements(entries) x));
 PERFORM maezo_d7_control._need(pg_catalog.jsonb_array_length(edges)<=1024 AND pg_catalog.jsonb_array_length(grants)<=1024,'P7D09');
 body:=pg_catalog.jsonb_build_object('protocol','maezo.d7-role-acl-manifest.v1','installation_id',installation,'roles',entries,'memberships',edges,'object_grants',grants,'operational_principals',operational);
 RETURN body||pg_catalog.jsonb_build_object('catalog_sha256',maezo_d7_control._sha(maezo_d7_control._canonical(body)));
END $d7$;
CREATE FUNCTION maezo_d7_control._receipt_incarnation(q pg_catalog.jsonb) RETURNS pg_catalog.uuid
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $d7$
DECLARE guarded jsonb;inc uuid;BEGIN
 PERFORM maezo_d7_control._identity('D guard-function owner',NULL);
 guarded:=maezo_d7_control.lock_provisioning_scope(q);
 SELECT database_incarnation INTO STRICT inc FROM maezo_d7_control."MZO_PROVISIONING_FENCE" WHERE tenant=guarded->'scope'->>'tenant' AND environment=guarded->'scope'->>'environment' AND engine_name=guarded->'scope'->>'engine_name';RETURN inc;
END $d7$;

