CREATE FUNCTION maezo_d7_control._immutable_mzo_provisioning_fence() RETURNS pg_catalog.trigger
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $d7$
BEGIN IF TG_OP='DELETE' THEN PERFORM maezo_d7_control._need(false,'P7D06');END IF;
 PERFORM maezo_d7_control._need((pg_catalog.to_jsonb(NEW)-ARRAY['database_incarnation','database_binding_bytes','database_binding_sha256','epoch','revision','owner_run_id','owner_subject','mode','candidate_sha256','trust_profile_sha256','current_generation_id','next_generation_id','controller_state','controller_revision','journal_revision','pending_index_sha256','settled_journal_sha256','managed_registry_sha256','controller_lease_deadline_ms','observed_at_ms','observation_deadline_ms','control_observation_sha256','database_observation_sha256','observation_pair_sha256','restore_reconciliation_sha256','recovery_reason','restore_state','updated_at_ms']::pg_catalog.text[])=(pg_catalog.to_jsonb(OLD)-ARRAY['database_incarnation','database_binding_bytes','database_binding_sha256','epoch','revision','owner_run_id','owner_subject','mode','candidate_sha256','trust_profile_sha256','current_generation_id','next_generation_id','controller_state','controller_revision','journal_revision','pending_index_sha256','settled_journal_sha256','managed_registry_sha256','controller_lease_deadline_ms','observed_at_ms','observation_deadline_ms','control_observation_sha256','database_observation_sha256','observation_pair_sha256','restore_reconciliation_sha256','recovery_reason','restore_state','updated_at_ms']::pg_catalog.text[]),'P7D06');RETURN NEW;END $d7$;
CREATE TRIGGER d7_immutable BEFORE UPDATE OR DELETE ON maezo_d7_control."MZO_PROVISIONING_FENCE" FOR EACH ROW EXECUTE FUNCTION maezo_d7_control._immutable_mzo_provisioning_fence();

